// Hotel Data Processing Script for n8n
// Processes Dutch hotel occupancy data and converts to clean JSON
// Error handling & observability aligned with README style (pared down):
// summary fields: header_rows_skipped, non_data_rows_skipped, missing_columns,
// used_fallback, successfully_processed, failed_validation, errors_count.

// -------------------- Constants & Utilities --------------------

const WEEKDAY_MAP = {
  ma: 'Monday',
  di: 'Tuesday',
  wo: 'Wednesday',
  do: 'Thursday',
  vr: 'Friday',
  za: 'Saturday',
  zo: 'Sunday',
};

// Hotel names to search for (case-insensitive contains match)
const HOTEL_NAMES = [
  'de Hoeve van Nunspeet',
  // Placeholder for 19 other hotel names - to be added later
  'andere klant 1',
  'andere klant 2',
  'andere klant 3',
  'andere klant 4',
  'andere klant 5',
  'andere klant 6',
  'andere klant 7',
  'andere klant 8',
  'andere klant 9',
  'andere klant 10',
  'andere klant 11',
  'andere klant 12',
  'andere klant 13',
  'andere klant 14',
  'andere klant 15',
  'andere klant 16',
  'andere klant 17',
  'andere klant 18',
  'andere klant 19',
];

// tolerant: optional comma, flexible spaces, strict DD-MM-YYYY
const DATE_PATTERN = /^(ma|di|wo|do|vr|za|zo),?\s+\d{2}-\d{2}-\d{4}$/i;

function isString(v) { return typeof v === 'string'; }

function isDateRow(cellValue) {
  if (!cellValue || !isString(cellValue)) return false;
  return DATE_PATTERN.test(cellValue.trim());
}

function extractWeekday(datumStr) {
  if (!datumStr || !isString(datumStr)) return 'Unknown';
  const head = datumStr.split(',')[0].trim().toLowerCase(); // supports "ma, ..." and "ma  ..."
  const abbr = head.split(/\s+/)[0];
  return WEEKDAY_MAP[abbr] || 'Unknown';
}

function parseDateToISO(datumStr) {
  if (!datumStr || !isString(datumStr)) return null;
  const m = datumStr.match(/\b(\d{2})-(\d{2})-(\d{4})\b/);
  if (!m) return null;
  const [_, dd, MM, yyyy] = m;
  return `${yyyy}-${MM}-${dd}`;
}

function toNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number') return isFinite(value) ? value : null;
  if (typeof value === 'string') {
    const cleaned = value
      .replace(/\s|\u00A0/g, '')
      .replace(/[€$]/g, '')
      .replace(/%/g, '')
      .replace(/,/g, '.') // treat comma as decimal
      .replace(/[^\d.\-]/g, '');
    const num = parseFloat(cleaned);
    return isNaN(num) ? null : num;
  }
  return null;
}

// -------------------- Hotel Name Extraction --------------------

/**
 * Extracts hotel name from first 3 rows by searching in both keys and values
 * Uses contains logic (case-insensitive) to find hotel name
 * Returns the clean hotel name from HOTEL_NAMES array or "error" if not found
 */
function extractHotelName(rows) {
  const searchRows = rows.slice(0, Math.min(3, rows.length));

  // Loop through each hotel name in the array
  for (const hotelName of HOTEL_NAMES) {
    const normalizedHotelName = hotelName.toLowerCase();

    // Search in all rows
    for (const row of searchRows) {
      // Search in column keys (property names)
      for (const key of Object.keys(row)) {
        if (!isString(key)) continue;
        const normalizedKey = key.trim().toLowerCase();

        if (normalizedKey.includes(normalizedHotelName)) {
          return hotelName; // return clean name from array
        }
      }

      // Search in values
      for (const value of Object.values(row)) {
        if (!isString(value)) continue;
        const normalizedValue = value.trim().toLowerCase();

        if (normalizedValue.includes(normalizedHotelName)) {
          return hotelName; // return clean name from array
        }
      }
    }
  }

  return 'error'; // no match found
}

// -------------------- Header Detection (improved) --------------------

// Normalize header labels: lowercase, trim, collapse spaces, remove punctuation & NBSP
function normalizeHeaderLabel(val) {
  if (!isString(val)) return '';
  return val
    .replace(/\u00A0/g, ' ')           // NBSP -> space
    .toLowerCase()
    .trim()
    .replace(/[.,:;]+/g, '')           // strip common punctuation
    .replace(/\s+/g, ' ');             // collapse spaces
}

/**
 * Improved header detection:
 * Prefer a row where row["Periode:"] == "Datum" (exact, case-insensitive),
 * AND the same row contains at least TWO of: "bezet", "accom"/"accom.", "totaal".
 * Fallback to heuristic scoring only if this strict check fails.
 */
function findHeaderRow(rows) {
  // Strategy 1: strict anchored detection
  for (let i = 0; i < Math.min(rows.length, 60); i++) {
    const row = rows[i] || {};
    const periodeVal = row['Periode:'];
    const normPeriode = normalizeHeaderLabel(periodeVal);
    if (normPeriode === 'datum') {
      const values = Object.values(row).map(normalizeHeaderLabel);
      let scoreTokens = 0;
      if (values.some(v => v === 'bezet')) scoreTokens++;
      if (values.some(v => v === 'totaal')) scoreTokens++;
      if (values.some(v => v === 'accom' || v.startsWith('accom'))) scoreTokens++;
      if (scoreTokens >= 2) {
        return { row, index: i };
      }
    }
  }

  // Strategy 2: heuristic (legacy) if the anchored search fails
  let best = null;
  for (let i = 0; i < Math.min(rows.length, 20); i++) {
    const row = rows[i];
    const entries = Object.entries(row);
    let score = 0;
    for (const [, v] of entries) {
      const s = normalizeHeaderLabel(v);
      if (!s) continue;
      if (s.includes('datum')) score += 2;
      if (s.includes('bezet')) score += 2;
      if (s.includes('accom')) score += 2;
      if (s.includes('totaal')) score += 2;
    }
    if (score >= 4) { // at least two signals
      best = { row, index: i };
      break;
    }
  }
  return best;
}

function createColumnMapping(headerRow) {
  const mapping = {};
  for (const [key, value] of Object.entries(headerRow)) {
    const s = normalizeHeaderLabel(value);
    if (!s) continue;

    // Prefer exact tokens
    if (s === 'datum') {
      mapping.date = key;
      continue;
    }
    if (s === 'bezet') {
      mapping.roomNights = key;
      continue;
    }
    if (s === 'totaal') {
      mapping.totalRevenue = key;
      continue;
    }
    // Accept common variant for accom
    if (s === 'accom' || s.startsWith('accom')) {
      mapping.roomRevenue = key;
      continue;
    }
    // F&B Revenue detection
    if (s === 'f&b' || s === 'fb' || s === 'f & b') {
      mapping.fbRevenue = key;
      continue;
    }
    // Other/Extras Revenue detection
    if (s === 'extras' || s === 'other' || s === 'overig') {
      mapping.otherRevenue = key;
      continue;
    }
  }
  return mapping;
}

// Provide fallback mapping if headers missing
function withFallback(mapping) {
  const m = { ...mapping };
  if (!m.date) m.date = 'Periode:';       // dataset uses this as the date column key
  if (!m.roomNights) m.roomNights = '_4'; // observed in sample
  if (!m.roomRevenue) m.roomRevenue = '_34';
  if (!m.fbRevenue) m.fbRevenue = '_35';           // F&B column
  if (!m.otherRevenue) m.otherRevenue = '_38';     // Extras/Other column
  if (!m.totalRevenue) m.totalRevenue = '_40';
  return m;
}

function computeMissingColumns(mapping) {
  const missing = [];
  if (!mapping.date) missing.push('date');
  if (!mapping.roomNights) missing.push('roomNights');
  if (!mapping.roomRevenue) missing.push('roomRevenue');
  if (!mapping.fbRevenue) missing.push('fbRevenue');
  if (!mapping.otherRevenue) missing.push('otherRevenue');
  if (!mapping.totalRevenue) missing.push('totalRevenue');
  return missing;
}

// -------------------- Row Processing --------------------

function processRowObject(rowObj, mapping) {
  const rawDateCell = rowObj[mapping.date];
  if (!rawDateCell || !isString(rawDateCell)) return { kind: 'skip' };

  const trimmed = rawDateCell.trim();

  // Common non-data lines to skip (do not treat as errors)
  const NON_DATA_MARKERS = new Set([
    'summary', 'type', 'revenue', 'ooo rooms', 'pseudorooms',
    'state', 'soort tarief', 'totaal', 'systeemdatum:'
  ]);
  if (NON_DATA_MARKERS.has(normalizeHeaderLabel(trimmed))) return { kind: 'skip' };

  // Must be a date row
  if (!isDateRow(trimmed)) {
    // Heuristic: contains dd-mm-yyyy somewhere but weekday missing/malformed -> error
    const hasDate = /\b\d{2}-\d{2}-\d{4}\b/.test(trimmed);
    if (hasDate) {
      return {
        kind: 'error',
        error: `Invalid date pattern: "${trimmed}" (expected "ma|di|wo|do|vr|za|zo, DD-MM-YYYY")`,
      };
    }
    return { kind: 'skip' };
  }

  const isoDate = parseDateToISO(trimmed);
  if (!isoDate) {
    return {
      kind: 'error',
      error: `Failed to parse date from "${trimmed}" (expected DD-MM-YYYY)`,
    };
  }

  const englishWeekday = extractWeekday(trimmed);

  // Parse numeric fields (warnings kept minimal; non-numeric => null)
  const rn = toNumber(rowObj[mapping.roomNights]);
  const accom = toNumber(rowObj[mapping.roomRevenue]);
  const fb = toNumber(rowObj[mapping.fbRevenue]);
  const other = toNumber(rowObj[mapping.otherRevenue]);
  const total = toNumber(rowObj[mapping.totalRevenue]);

  const out = {
    Date: isoDate,
    Weekday: englishWeekday,
    RoomNights: rn,
    RoomRevenue: accom,
    FB_Revenue: fb,
    OtherRevenue: other,
    TotalRevenue: total,
  };

  // Validation warnings
  const warnings = [];

  // Check: TotalRevenue < RoomRevenue (legacy check)
  if (total != null && accom != null && total < accom) {
    warnings.push(`Mismatch: TotalRevenue (${total}) < RoomRevenue (${accom})`);
  }

  // Check: Sum validation (RoomRevenue + FB_Revenue + OtherRevenue should equal TotalRevenue)
  if (accom != null && fb != null && other != null && total != null) {
    const calculatedSum = accom + fb + other;
    const tolerance = 0.01; // Allow 1 cent tolerance for floating point
    const difference = Math.abs(calculatedSum - total);
    if (difference > tolerance) {
      warnings.push(`Revenue sum mismatch: RoomRevenue (${accom.toFixed(2)}) + FB_Revenue (${fb.toFixed(2)}) + OtherRevenue (${other.toFixed(2)}) = ${calculatedSum.toFixed(2)}, but TotalRevenue = ${total.toFixed(2)} (diff: ${difference.toFixed(2)})`);
    }
  }

  if (warnings.length) out._warnings = warnings;

  return { kind: 'ok', value: out };
}

// -------------------- Main Processing --------------------

const items = $input.all();
const allResults = [];
let totalRows = 0;
let headerRowsSkipped = 0;
let nonDataRowsSkipped = 0;
let successfullyProcessed = 0;
let failedValidation = 0;

const failedRows = []; // collected row-level errors
let usedFallbackAny = false;
const aggMissing = [];
let hotelNameExtracted = null; // track extracted hotel name
let isFirstDataRow = true; // flag to add hotelName to first data row only

// Track column detection results for testing/debugging
let columnDetectionLog = [];

for (const item of items) {
  let rows;
  const inputData = item.json;
  if (Array.isArray(inputData)) rows = inputData;
  else if (inputData && typeof inputData === 'object') rows = [inputData];
  else rows = [];

  totalRows += rows.length;

  // Extract hotel name from first 3 rows (only once)
  if (hotelNameExtracted === null && rows.length > 0) {
    hotelNameExtracted = extractHotelName(rows);
  }

  // Header detection (improved)
  const headerInfo = findHeaderRow(rows);
  let mapping = {};
  let usedFallback = false;

  if (headerInfo) {
    mapping = createColumnMapping(headerInfo.row);
    headerRowsSkipped += (headerInfo.index + 1); // start after header

    // Log detected columns for debugging
    columnDetectionLog.push({
      headerRowIndex: headerInfo.index,
      detectedMappings: { ...mapping },
      headerRowValues: Object.entries(headerInfo.row)
        .filter(([k, v]) => v && isString(v) && v.trim())
        .map(([k, v]) => ({ key: k, value: v }))
    });
  }

  // If some are missing, apply fallback
  const preFallbackMissing = computeMissingColumns(mapping);
  if (preFallbackMissing.length) {
    mapping = withFallback(mapping);
    usedFallback = true;
  }

  const missingColumnsAfter = computeMissingColumns(mapping);
  for (const k of missingColumnsAfter) if (!aggMissing.includes(k)) aggMissing.push(k);
  if (usedFallback) usedFallbackAny = true;

  // Critical error: no data or still no date column
  if (rows.length === 0) {
    return [
      {
        json: {
          success: false,
          message: 'No occupancy data found. Please provide an array of row objects.',
        },
      },
    ];
  }
  if (missingColumnsAfter.includes('date')) {
    return [
      {
        json: {
          success: false,
          message:
            'CRITICAL ERROR: Cannot process data - missing required columns.\n' +
            'Required column: Datum (date column with weekday + DD-MM-YYYY).',
        },
      },
    ];
  }

  // Start processing after header row if present
  const startIndex = headerInfo ? headerInfo.index + 1 : 0;

  for (let i = startIndex; i < rows.length; i++) {
    const rowObj = rows[i];
    const res = processRowObject(rowObj, mapping);

    if (res.kind === 'ok') {
      // Add hotelName to first data row only
      if (isFirstDataRow) {
        res.value.hotelName = hotelNameExtracted;
        isFirstDataRow = false;
      }

      allResults.push({ json: res.value });
      successfullyProcessed += 1;
    } else if (res.kind === 'error') {
      failedValidation += 1;
      failedRows.push({
        error: true,
        row_index: i,
        validation_errors: [res.error],
        raw_data: rowObj,
      });
    } else {
      nonDataRowsSkipped += 1; // kind === 'skip'
    }
  }
}

// If everything failed (no successes) and we had row-level errors -> Critical style
if (successfullyProcessed === 0 && failedValidation > 0) {
  return [
    {
      json: {
        success: false,
        message: `Failed to process any valid rows. ${failedValidation} rows failed validation.\nPlease check the error details in the output.`,
      },
    },
  ];
}

// Generate warnings for missing columns (F&B and OtherRevenue)
const columnWarnings = [];
if (aggMissing.includes('fbRevenue')) {
  columnWarnings.push('WARNING: F&B Revenue column not detected. Using fallback column _35 or null values.');
}
if (aggMissing.includes('otherRevenue')) {
  columnWarnings.push('WARNING: Other/Extras Revenue column not detected. Using fallback column _38 or null values.');
}

// Push summary (ONLY requested observability fields)
allResults.push({
  json: {
    _summary: true,
    header_rows_skipped: headerRowsSkipped,
    non_data_rows_skipped: nonDataRowsSkipped,
    missing_columns: aggMissing,          // after fallback
    missing_column_warnings: columnWarnings,
    used_fallback: usedFallbackAny,       // should be false for your sample now
    successfully_processed: successfullyProcessed,
    failed_validation: failedValidation,
    errors_count: failedValidation > 0 ? 1 : 0,
    column_detection_log: columnDetectionLog,  // For testing column detection
  },
});

// Push errors item if any
if (failedRows.length > 0) {
  allResults.push({
    json: {
      _errors: true,
      failed_rows: failedRows,
    },
  });
}

return allResults;

/**
 * Hotel Revenue Forecasting System - Module 1: Data Parser & Validator
 * 
 * Handles:
 * - Loading and parsing all input data sources
 * - Comprehensive validation of data integrity
 * - Date parsing and normalization
 * - Data quality warnings and errors
 * - Preparation of clean data structures for forecasting engine
 * 
 * Expected Inputs:
 * 1. current_housestate.json - 90 days forward OTB data
 * 2. context.xlsx (7 sheets via separate CSVs or single object):
 *    - Hotel_Info
 *    - Events
 *    - Trends
 *    - Historical_Reservations
 *    - Historical_Housestate
 *    - Previous_Forecast
 *    - Forecast_Accuracy_History
 */

class DataParserValidator {
  constructor() {
    this.errors = [];
    this.warnings = [];
    this.validationResults = {
      currentHousestate: { valid: false, recordCount: 0 },
      hotelInfo: { valid: false },
      events: { valid: false, recordCount: 0 },
      trends: { valid: false, recordCount: 0 },
      historicalReservations: { valid: false, recordCount: 0 },
      historicalHousestate: { valid: false, recordCount: 0 },
      previousForecast: { valid: false, recordCount: 0 },
      forecastAccuracyHistory: { valid: false, recordCount: 0 }
    };
  }

  /**
   * Main parsing function - orchestrates all data loading
   */
  parseAllData(inputData) {
    try {
      // Parse current housestate (OTB data)
      const currentHousestate = this.parseCurrentHousestate(inputData.currentHousestate);

      // Parse hotel configuration
      const hotelInfo = this.parseHotelInfo(inputData.hotelInfo);

      // Parse events
      const events = this.parseEvents(inputData.events);

      // Parse trends (may be placeholder)
      const trends = this.parseTrends(inputData.trends);

      // Parse historical reservations
      const historicalReservations = this.parseHistoricalReservations(inputData.historicalReservations);

      // Parse historical housestate
      const historicalHousestate = this.parseHistoricalHousestate(inputData.historicalHousestate);

      // Parse previous forecast
      const previousForecast = this.parsePreviousForecast(inputData.previousForecast);

      // Parse forecast accuracy history
      const forecastAccuracyHistory = this.parseForecastAccuracyHistory(inputData.forecastAccuracyHistory);

      // Flag outliers in historical data (dynamic thresholds)
      this.flagOutliers(historicalHousestate, hotelInfo);

      // Run cross-validation checks
      this.runCrossValidation({
        currentHousestate,
        hotelInfo,
        events,
        historicalReservations,
        historicalHousestate,
        previousForecast
      });

      return {
        success: this.errors.length === 0,
        data: {
          currentHousestate,
          hotelInfo,
          events,
          trends,
          historicalReservations,
          historicalHousestate,
          previousForecast,
          forecastAccuracyHistory
        },
        errors: this.errors,
        warnings: this.warnings,
        validationResults: this.validationResults
      };

    } catch (error) {
      this.errors.push({
        type: 'CRITICAL',
        source: 'DataParser',
        message: `Fatal error during data parsing: ${error.message}`,
        timestamp: new Date().toISOString()
      });

      return {
        success: false,
        data: null,
        errors: this.errors,
        warnings: this.warnings,
        validationResults: this.validationResults
      };
    }
  }

  /**
   * Parse Current Housestate (OTB Data)
   * Expected: Array with hotel name as key containing 90 days of data
   */
  parseCurrentHousestate(rawData) {
    const source = 'CurrentHousestate';

    try {
      // Handle both array format and direct object format
      let hotelData;

      if (Array.isArray(rawData)) {
        // Find the hotel data object
        const hotelObj = rawData.find(item => {
          const keys = Object.keys(item);
          return keys.some(key => key !== 'Historical Housestats' && key !== 'Historical Reservations');
        });

        if (!hotelObj) {
          this.errors.push({
            type: 'CRITICAL',
            source,
            message: 'Could not find hotel data in current housestate array'
          });
          return [];
        }

        // Get the hotel name key
        const hotelName = Object.keys(hotelObj).find(key => 
          key !== 'Historical Housestats' && key !== 'Historical Reservations'
        );
        hotelData = hotelObj[hotelName];

      } else if (typeof rawData === 'object' && rawData !== null) {
        hotelData = rawData;
      } else {
        this.errors.push({
          type: 'CRITICAL',
          source,
          message: 'Invalid current housestate format'
        });
        return [];
      }

      if (!Array.isArray(hotelData)) {
        this.errors.push({
          type: 'CRITICAL',
          source,
          message: 'Current housestate hotel data is not an array'
        });
        return [];
      }

      // Validate we have close to 90 days
      if (hotelData.length < 85 || hotelData.length > 95) {
        this.warnings.push({
          type: 'WARNING',
          source,
          message: `Expected ~90 days of data, found ${hotelData.length} days`
        });
      }

      // Parse and validate each day
      const parsedData = hotelData.map((day, index) => {
        const parsed = {
          date: this.parseDate(day.Date, source, `row ${index + 1}`),
          weekday: this.validateWeekday(day.Weekday, source, `row ${index + 1}`),
          roomNights: this.parseNumber(day.RoomNights, source, `row ${index + 1}`, 'RoomNights'),
          roomRevenue: this.parseNumber(day.RoomRevenue, source, `row ${index + 1}`, 'RoomRevenue'),
          totalRevenue: this.parseNumber(day.TotalRevenue, source, `row ${index + 1}`, 'TotalRevenue'),
          fbRevenue: day.FB_Revenue != null ? this.parseNumber(day.FB_Revenue, source, `row ${index + 1}`, 'FB_Revenue') : null,
          otherRevenue: day.OtherRevenue != null ? this.parseNumber(day.OtherRevenue, source, `row ${index + 1}`, 'OtherRevenue') : null,
          rawWarnings: day._warnings || []
        };

        // Validate data quality
        if (parsed.totalRevenue < parsed.roomRevenue && parsed.totalRevenue > 0) {
          this.warnings.push({
            type: 'WARNING',
            source,
            message: `${parsed.date}: TotalRevenue (${parsed.totalRevenue.toFixed(2)}) < RoomRevenue (${parsed.roomRevenue.toFixed(2)})`
          });
        }

        if (parsed.totalRevenue < 0) {
          this.warnings.push({
            type: 'WARNING',
            source,
            message: `${parsed.date}: Negative TotalRevenue (${parsed.totalRevenue.toFixed(2)})`
          });
        }

        if (parsed.roomNights < 0) {
          this.warnings.push({
            type: 'WARNING',
            source,
            message: `${parsed.date}: Negative RoomNights value (${parsed.roomNights})`
          });
        }

        return parsed;
      });

      // Ensure chronological order
      const sorted = parsedData.sort((a, b) => a.date - b.date);

      this.validationResults.currentHousestate = {
        valid: true,
        recordCount: sorted.length,
        dateRange: {
          start: sorted[0].date.toISOString().split('T')[0],
          end: sorted[sorted.length - 1].date.toISOString().split('T')[0]
        }
      };

      return sorted;

    } catch (error) {
      this.errors.push({
        type: 'CRITICAL',
        source,
        message: `Error parsing current housestate: ${error.message}`
      });
      return [];
    }
  }

  /**
   * Parse Hotel Info
   */
  parseHotelInfo(rawData) {
    const source = 'HotelInfo';

    try {
      // Handle both array format (CSV) and single object
      let hotelData = rawData;

      if (Array.isArray(rawData)) {
        if (rawData.length === 0) {
          this.errors.push({
            type: 'CRITICAL',
            source,
            message: 'Hotel info array is empty'
          });
          return null;
        }
        hotelData = rawData[0]; // Take first row
      }

      const parsed = {
        maxRooms: this.parseNumber(hotelData.Max_Rooms, source, 'Max_Rooms', 'Max_Rooms', true),
        maxPersons: this.parseNumber(hotelData.Max_Persons, source, 'Max_Persons', 'Max_Persons'),
        minStayDuration: this.parseNumber(hotelData.Min_Stay_Duration, source, 'Min_Stay_Duration', 'Min_Stay_Duration') || 1,
        maxStayDuration: this.parseNumber(hotelData.Max_Stay_Duration, source, 'Max_Stay_Duration', 'Max_Stay_Duration') || 30,
        hotelName: String(hotelData.Hotel_Name || 'Unknown Hotel'),
        hotelAddress: String(hotelData.Hotel_Address || ''),
        hotelType: String(hotelData.Hotel_Type || 'Unknown'),
        seasonalHotel: String(hotelData.Seasonal_Hotel || 'No').toLowerCase() === 'yes',
        areaType: String(hotelData.Area_Type || 'Unknown'),
        growthTrend: this.parseNumber(hotelData.Growth_Trend, source, 'Growth_Trend', 'Growth_Trend') || 1.0
      };

      // Validate growth trend limits
      if (parsed.growthTrend < 0.5 || parsed.growthTrend > 2.0) {
        this.errors.push({
          type: 'ERROR',
          source,
          message: `Growth_Trend ${parsed.growthTrend} outside acceptable range (0.5 - 2.0)`
        });
        parsed.growthTrend = Math.max(0.5, Math.min(2.0, parsed.growthTrend));
      }

      // Validate max rooms
      if (parsed.maxRooms < 1 || parsed.maxRooms > 500) {
        this.errors.push({
          type: 'ERROR',
          source,
          message: `Max_Rooms ${parsed.maxRooms} seems unrealistic`
        });
      }

      this.validationResults.hotelInfo = { valid: true };

      return parsed;

    } catch (error) {
      this.errors.push({
        type: 'CRITICAL',
        source,
        message: `Error parsing hotel info: ${error.message}`
      });
      return null;
    }
  }

  /**
   * Parse Events
   */
  parseEvents(rawData) {
    const source = 'Events';

    try {
      if (!Array.isArray(rawData)) {
        this.warnings.push({
          type: 'WARNING',
          source,
          message: 'No events data provided (this is optional)'
        });
        this.validationResults.events = { valid: true, recordCount: 0 };
        return [];
      }

      const parsed = rawData.map((event, index) => {
        return {
          eventName: String(event.Event_Name || `Event ${index + 1}`),
          startDate: this.parseDate(event.Start_Date, source, `row ${index + 1}`),
          endDate: this.parseDate(event.End_Date, source, `row ${index + 1}`),
          pickupImpact: this.parseNumber(event.Pickup_Impact, source, `row ${index + 1}`, 'Pickup_Impact') || 0,
          overrideMaxRooms: event.Override_Max_Rooms ?
            this.parseNumber(event.Override_Max_Rooms, source, `row ${index + 1}`, 'Override_Max_Rooms') :
            null,
          description: String(event.Description || '')
        };
      }).filter(event => event.startDate && event.endDate);

      this.validationResults.events = {
        valid: true,
        recordCount: parsed.length
      };

      return parsed;

    } catch (error) {
      this.warnings.push({
        type: 'WARNING',
        source,
        message: `Error parsing events (non-critical): ${error.message}`
      });
      this.validationResults.events = { valid: true, recordCount: 0 };
      return [];
    }
  }

  /**
   * Parse Trends (Placeholder for future use)
   */
  parseTrends(rawData) {
    const source = 'Trends';

    try {
      if (!Array.isArray(rawData) || rawData.length === 0) {
        this.warnings.push({
          type: 'INFO',
          source,
          message: 'No trends data provided (placeholder for future use)'
        });
        this.validationResults.trends = { valid: true, recordCount: 0 };
        return [];
      }

      // Future: Parse seasonal factors, channel trends, etc.
      this.validationResults.trends = { valid: true, recordCount: rawData.length };
      return rawData;

    } catch (error) {
      this.warnings.push({
        type: 'WARNING',
        source,
        message: `Error parsing trends (non-critical): ${error.message}`
      });
      this.validationResults.trends = { valid: true, recordCount: 0 };
      return [];
    }
  }

  /**
   * Parse Historical Reservations
   */
  parseHistoricalReservations(rawData) {
    const source = 'HistoricalReservations';

    try {
      // Handle both array format and nested format
      let reservationsData = rawData;

      if (Array.isArray(rawData)) {
        const reservationsObj = rawData.find(item => item['Historical Reservations']);
        if (reservationsObj) {
          reservationsData = reservationsObj['Historical Reservations'];
        }
      }

      if (!Array.isArray(reservationsData)) {
        this.errors.push({
          type: 'CRITICAL',
          source,
          message: 'Historical reservations data is not an array'
        });
        return [];
      }

      // Check data age
      const now = new Date();
      const sixMonthsAgo = new Date(now);
      sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);

      let oldestReservation = null;
      let newestReservation = null;

      const parsed = reservationsData
        .filter(res => !res.cancelledAt && !res.cancelled_at) // Exclude cancelled reservations
        .map((res, index) => {
          // Support both database field names (Title_Case) and extraction output (snake_case)
          const arrivalDate = this.parseDate(res.Arrival_Date || res.arrival_date, source, `row ${index + 1}`);
          const departureDate = this.parseDate(res.Departure_Date || res.departure_date, source, `row ${index + 1}`);
          const createdAt = this.parseDate(res.Reservation_created_at || res.created_at, source, `row ${index + 1}`);

          // Track oldest/newest
          if (!oldestReservation || arrivalDate < oldestReservation) {
            oldestReservation = arrivalDate;
          }
          if (!newestReservation || arrivalDate > newestReservation) {
            newestReservation = arrivalDate;
          }

          return {
            arrivalDate,
            departureDate,
            nights: this.parseNumber(res.Nights || res.nights, source, `row ${index + 1}`, 'Nights') || 1,
            weekdayArrival: this.validateWeekday(res.Weekday_Arrival || res.weekday_arrival, source, `row ${index + 1}`),
            channel: String(res.Channel || res.channel || 'Unknown'),
            rateCode: String(res.Rate_Code || res.rate_code || ''),
            roomNights: this.parseNumber(res.Room_Nights || res.nights, source, `row ${index + 1}`, 'Room_Nights') || 1,
            averagePrice: this.parseNumber(res.averagePrice || res.average_price, source, `row ${index + 1}`, 'averagePrice') || 0,
            totalPrice: this.parseNumber(res.totalPrice || res.total_price, source, `row ${index + 1}`, 'totalPrice') || 0,
            createdAt,
            leadtime: arrivalDate && createdAt ?
              Math.floor((arrivalDate - createdAt) / (1000 * 60 * 60 * 24)) :
              null
          };
        });

      // Check if data is outdated
      if (newestReservation && newestReservation < sixMonthsAgo) {
        this.warnings.push({
          type: 'WARNING',
          source,
          message: `Historical reservations data is outdated (newest: ${newestReservation.toISOString().split('T')[0]}). Using 2-year-old data as fallback.`
        });
      }

      this.validationResults.historicalReservations = {
        valid: true,
        recordCount: parsed.length,
        dateRange: oldestReservation && newestReservation ? {
          start: oldestReservation.toISOString().split('T')[0],
          end: newestReservation.toISOString().split('T')[0]
        } : null
      };

      return parsed;

    } catch (error) {
      this.errors.push({
        type: 'CRITICAL',
        source,
        message: `Error parsing historical reservations: ${error.message}`
      });
      return [];
    }
  }

  /**
   * Parse Historical Housestate
   */
  parseHistoricalHousestate(rawData) {
    const source = 'HistoricalHousestate';

    try {
      // Handle both array format and nested format
      let housestateData = rawData;

      if (Array.isArray(rawData)) {
        const housestateObj = rawData.find(
          item => item['Historical Housestats'] || item['Historical Housestates']
        );
        if (housestateObj) {
          housestateData =
            housestateObj['Historical Housestats'] || housestateObj['Historical Housestates'];
        }
      }


      if (!Array.isArray(housestateData)) {
        this.errors.push({
          type: 'CRITICAL',
          source,
          message: 'Historical housestate data is not an array'
        });
        return [];
      }

      // Check we have at least 1 year of data
      if (housestateData.length < 365) {
        this.warnings.push({
          type: 'WARNING',
          source,
          message: `Historical housestate has only ${housestateData.length} days (recommended: 365+)`
        });
      }

      const parsed = housestateData.map((day, index) => {
        return {
          date: this.parseDate(day.Date, source, `row ${index + 1}`),
          weekday: this.validateWeekday(day.Weekday, source, `row ${index + 1}`),
          roomNights: this.parseNumber(day.RoomNights, source, `row ${index + 1}`, 'RoomNights'),
          roomRevenue: this.parseNumber(day.RoomRevenue, source, `row ${index + 1}`, 'RoomRevenue'),
          totalRevenue: this.parseNumber(day.TotalRevenue, source, `row ${index + 1}`, 'TotalRevenue'),
          fbRevenue: day.FB_Revenue != null ? this.parseNumber(day.FB_Revenue, source, `row ${index + 1}`, 'FB_Revenue') : null,
          otherRevenue: day.OtherRevenue != null ? this.parseNumber(day.OtherRevenue, source, `row ${index + 1}`, 'OtherRevenue') : null
        };
      });

      // Sort chronologically (filter out null dates first)
      const sorted = parsed.filter(day => day.date !== null).sort((a, b) => a.date - b.date);

      this.validationResults.historicalHousestate = {
        valid: sorted.length > 0,
        recordCount: sorted.length,
        dateRange: sorted.length > 0 ? {
          start: sorted[0].date.toISOString().split('T')[0],
          end: sorted[sorted.length - 1].date.toISOString().split('T')[0]
        } : null
      };

      return sorted;

    } catch (error) {
      this.warnings.push({
        type: 'WARNING',
        source,
        message: `Error parsing historical housestate: ${error.message} (Will use limited historical data)`
      });
      this.validationResults.historicalHousestate = { valid: true, recordCount: 0 };
      return [];
    }
  }

  /**
   * Parse Previous Forecast
   */
  parsePreviousForecast(rawData) {
    const source = 'PreviousForecast';

    try {
      // Handle nested format
      let forecastData = rawData;

      if (Array.isArray(rawData)) {
        const forecastObj = rawData.find(item => item['Previous Forecasts']);
        if (forecastObj) {
          forecastData = forecastObj['Previous Forecasts'];
        }
      }

      if (!Array.isArray(forecastData) || forecastData.length === 0) {
        this.warnings.push({
          type: 'INFO',
          source,
          message: 'No previous forecast available (expected for first run)'
        });
        this.validationResults.previousForecast = { valid: true, recordCount: 0 };
        return [];
      }

      const parsed = forecastData
        .filter(day => day.Stay_Date !== null && day.Stay_Date !== undefined) // Filter out all-null records
        .map((day, index) => {
          return {
            stayDate: this.parseDate(day.Stay_Date, source, `row ${index + 1}`),
            forecastedRoomNights: this.parseNumber(day.Room_Nights_Final, source, `row ${index + 1}`, 'Room_Nights_Final'),
            forecastedRoomRevenue: this.parseNumber(day.Room_Revenue, source, `row ${index + 1}`, 'Room_Revenue'),
            forecastedTotalRevenue: this.parseNumber(day.Total_Revenue, source, `row ${index + 1}`, 'Total_Revenue'),
            forecastedADR: this.parseNumber(day.ADR, source, `row ${index + 1}`, 'ADR'),
            forecastedOccupancy: this.parseNumber(day.Occupancy_Pct, source, `row ${index + 1}`, 'Occupancy_Pct')
          };
        });

      // If all records were filtered out (all null), treat as empty
      if (parsed.length === 0) {
        this.warnings.push({
          type: 'INFO',
          source,
          message: 'No previous forecast available (expected for first run)'
        });
      }

      this.validationResults.previousForecast = {
        valid: true,
        recordCount: parsed.length
      };

      return parsed;

    } catch (error) {
      this.warnings.push({
        type: 'WARNING',
        source,
        message: `Error parsing previous forecast (non-critical): ${error.message}`
      });
      this.validationResults.previousForecast = { valid: true, recordCount: 0 };
      return [];
    }
  }

  /**
   * Parse Forecast Accuracy History
   */
  parseForecastAccuracyHistory(rawData) {
    const source = 'ForecastAccuracyHistory';

    try {
      // Handle nested format
      let accuracyData = rawData;

      if (Array.isArray(rawData)) {
        const accuracyObj = rawData.find(item => item['Forecast Accuracy History']);
        if (accuracyObj) {
          accuracyData = accuracyObj['Forecast Accuracy History'];
        }
      }

      if (!Array.isArray(accuracyData) || accuracyData.length === 0) {
        this.warnings.push({
          type: 'INFO',
          source,
          message: 'No forecast accuracy history available (expected for first run)'
        });
        this.validationResults.forecastAccuracyHistory = { valid: true, recordCount: 0 };
        return [];
      }

      const parsed = accuracyData
        .filter(entry => entry.Week_Date !== null && entry.Week_Date !== undefined) // Filter out all-null records
        .map((entry, index) => {
          return {
            weekEnding: this.parseDate(entry.Week_Ending || entry.Week_Date, source, `row ${index + 1}`),
            accuracyRoomNights: this.parseNumber(entry.Accuracy_Room_Nights || entry.Accuracy_RoomNights_1w, source, `row ${index + 1}`, 'Accuracy_Room_Nights'),
            accuracyRoomRevenue: this.parseNumber(entry.Accuracy_Room_Revenue || entry.Accuracy_RoomRevenue_1w, source, `row ${index + 1}`, 'Accuracy_Room_Revenue'),
            accuracyTotalRevenue: this.parseNumber(entry.Accuracy_Total_Revenue || entry.Accuracy_TotalRevenue_1w, source, `row ${index + 1}`, 'Accuracy_Total_Revenue'),
            accuracyADR: this.parseNumber(entry.Accuracy_ADR, source, `row ${index + 1}`, 'Accuracy_ADR'),
            accuracyOccupancy: this.parseNumber(entry.Accuracy_Occupancy, source, `row ${index + 1}`, 'Accuracy_Occupancy')
          };
        });

      // If all records were filtered out (all null), treat as empty
      if (parsed.length === 0) {
        this.warnings.push({
          type: 'INFO',
          source,
          message: 'No forecast accuracy history available (expected for first run)'
        });
      }

      this.validationResults.forecastAccuracyHistory = {
        valid: true,
        recordCount: parsed.length
      };

      return parsed;

    } catch (error) {
      this.warnings.push({
        type: 'WARNING',
        source,
        message: `Error parsing forecast accuracy history (non-critical): ${error.message}`
      });
      this.validationResults.forecastAccuracyHistory = { valid: true, recordCount: 0 };
      return [];
    }
  }

  /**
   * Flag outlier days in historical housestate using dynamic thresholds
   * - Room nights: > 1.5 × maxRooms or < 0
   * Flagged days are marked with isOutlier = true for exclusion in analysis
   * Future: ADR range check (configurable per hotel via Hotel Info)
   */
  flagOutliers(historicalHousestate, hotelInfo) {
    const source = 'OutlierDetection';
    const maxRoomNights = hotelInfo.maxRooms * 1.5;

    let outlierCount = 0;

    historicalHousestate.forEach(day => {
      day.isOutlier = false;

      // Room nights check
      if (day.roomNights > maxRoomNights || day.roomNights < 0) {
        day.isOutlier = true;
        day.outlierReason = `RoomNights ${day.roomNights} outside valid range (0–${maxRoomNights.toFixed(0)})`;
      }

      if (day.isOutlier) outlierCount++;
    });

    // Warn if too many outliers
    const totalDays = historicalHousestate.length;
    const outlierPct = totalDays > 0 ? (outlierCount / totalDays) * 100 : 0;

    if (outlierCount > 0) {
      this.warnings.push({
        type: 'INFO',
        source,
        message: `${outlierCount} of ${totalDays} historical days flagged as outliers (${outlierPct.toFixed(1)}%)`
      });
    }

    if (outlierPct > 10) {
      this.warnings.push({
        type: 'WARNING',
        source,
        message: `More than 10% of historical data flagged as outliers (${outlierPct.toFixed(1)}%). Consider reviewing data quality.`
      });
    }
  }

  /**
   * Cross-validation checks between datasets
   */
  runCrossValidation(datasets) {
    const source = 'CrossValidation';

    // Check if current housestate dates align with calendar
    if (datasets.currentHousestate.length > 0) {
      const firstDate = datasets.currentHousestate[0].date;
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      const daysDiff = Math.floor((firstDate - today) / (1000 * 60 * 60 * 24));

      if (daysDiff < -7 || daysDiff > 7) {
        this.warnings.push({
          type: 'WARNING',
          source,
          message: `Current housestate starts ${Math.abs(daysDiff)} days ${daysDiff > 0 ? 'in the future' : 'in the past'}`
        });
      }
    }

    // Check if historical data overlaps with current forecast period
    if (datasets.historicalHousestate.length > 0 && datasets.currentHousestate.length > 0) {
      const histEnd = datasets.historicalHousestate[datasets.historicalHousestate.length - 1].date;
      const currentStart = datasets.currentHousestate[0].date;

      const gapDays = Math.floor((currentStart - histEnd) / (1000 * 60 * 60 * 24));

      if (gapDays < -30) {
        this.warnings.push({
          type: 'WARNING',
          source,
          message: `Historical data overlaps with current period by ${Math.abs(gapDays)} days`
        });
      }
    }

    // Check max rooms consistency
    if (datasets.hotelInfo && datasets.currentHousestate.length > 0) {
      const maxRoomsOTB = Math.max(...datasets.currentHousestate.map(d => d.roomNights));

      if (maxRoomsOTB > datasets.hotelInfo.maxRooms) {
        this.warnings.push({
          type: 'WARNING',
          source,
          message: `OTB data shows ${maxRoomsOTB} room nights, but Max_Rooms is ${datasets.hotelInfo.maxRooms}`
        });
      }
    }
  }

  /**
   * Helper: Parse date from various formats
   */
  parseDate(value, source, context) {
    if (!value) {
      this.warnings.push({
        type: 'WARNING',
        source,
        message: `Missing date value at ${context}`
      });
      return null;
    }

    try {
      const date = new Date(value);

      if (isNaN(date.getTime())) {
        this.warnings.push({
          type: 'WARNING',
          source,
          message: `Invalid date '${value}' at ${context}`
        });
        return null;
      }

      return date;

    } catch (error) {
      this.warnings.push({
        type: 'WARNING',
        source,
        message: `Error parsing date '${value}' at ${context}: ${error.message}`
      });
      return null;
    }
  }

  /**
   * Helper: Parse and validate number
   */
  parseNumber(value, source, context, fieldName, required = false) {
    if (value === null || value === undefined || value === '') {
      if (required) {
        this.errors.push({
          type: 'ERROR',
          source,
          message: `Missing required field '${fieldName}' at ${context}`
        });
      }
      return 0;
    }

    const num = Number(value);

    if (isNaN(num)) {
      this.warnings.push({
        type: 'WARNING',
        source,
        message: `Invalid number '${value}' for ${fieldName} at ${context}`
      });
      return 0;
    }

    return num;
  }

  /**
   * Helper: Validate weekday
   */
  validateWeekday(value, source, context) {
    const validWeekdays = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

    if (!value || !validWeekdays.includes(value)) {
      this.warnings.push({
        type: 'WARNING',
        source,
        message: `Invalid weekday '${value}' at ${context}`
      });
      return 'Unknown';
    }

    return value;
  }

  /**
   * Generate validation report
   */
  getValidationReport() {
    return {
      summary: {
        totalErrors: this.errors.length,
        totalWarnings: this.warnings.length,
        criticalErrors: this.errors.filter(e => e.type === 'CRITICAL').length,
        canProceed: this.errors.filter(e => e.type === 'CRITICAL').length === 0
      },
      errors: this.errors,
      warnings: this.warnings,
      validationResults: this.validationResults
    };
  }
}

