];

// Dutch to English weekday mapping
const WEEKDAY_MAP = {
  'ma': 'Monday',
  'di': 'Tuesday',
  'wo': 'Wednesday',
  'do': 'Thursday',
  'vr': 'Friday',
  'za': 'Saturday',
  'zo': 'Sunday'
};

// -------------------- Hotel Name Extraction --------------------

function isString(val) {
  return typeof val === 'string' && val.trim().length > 0;
}

function extractHotelName(rows) {
  const searchRows = rows.slice(0, Math.min(3, rows.length));
  for (const hotelName of HOTEL_NAMES) {
    const normalizedHotelName = hotelName.toLowerCase();
    for (const row of searchRows) {
      for (const key of Object.keys(row)) {
        if (!isString(key)) continue;
        if (key.trim().toLowerCase().includes(normalizedHotelName)) {
          return hotelName;
        }
      }
      for (const value of Object.values(row)) {
        if (!isString(value)) continue;
        if (value.trim().toLowerCase().includes(normalizedHotelName)) {
          return hotelName;
        }
      }
    }
  }
  return null;
}

// -------------------- Column Detection --------------------

function detectColumnMapping(rows) {
  const headerPatterns = {
    reservationId: ['Res. #', 'Res.#', 'Res #', 'Reserveringsnummer', 'Reserverings nr'],
    createdAt: ['Aanmaak'],
    arrival: ['Aankomst'],
    departure: ['Vertrek'],
    nights: ['Nachten'],
    rateCode: ['Prijscode'],
    channel: ['Kanaal'],
    status: ['Res. status', 'Status'],
    cancelledAt: ['Geannuleerd op', 'Geannuleerd'],
    averagePrice: ['Gem. prijs'],
    totalPrice: ['Totaal']
  };

  const mapping = {
    columns: {},
    missingColumns: [],
    usedFallback: false,
    detectionMethod: 'header'
  };

  for (let i = 0; i < Math.min(10, rows.length); i++) {
    const row = rows[i];
    for (const [key, value] of Object.entries(row)) {
      if (!value || typeof value !== 'string') continue;
      const cellValue = value.trim();
      for (const [fieldName, patterns] of Object.entries(headerPatterns)) {
        for (const pattern of patterns) {
          if (cellValue === pattern) {
            mapping.columns[fieldName] = key;
            break;
          }
        }
      }
    }
    if (mapping.columns.arrival && mapping.columns.departure && mapping.columns.createdAt) {
      for (const fieldName of Object.keys(headerPatterns)) {
        if (!mapping.columns[fieldName]) {
          mapping.missingColumns.push(fieldName);
        }
      }
      return mapping;
    }
  }

  console.log('Warning: Could not detect header row, using default column positions');
  mapping.usedFallback = true;
  mapping.detectionMethod = 'fallback';
  mapping.columns = {
    reservationId: '_0',
    createdAt: '_1',
    arrival: '_2',
    departure: '_3',
    nights: '_7',
    rateCode: '_8',
    channel: '_10',
    averagePrice: '_12',
    totalPrice: '_13',
    status: '_15',
    cancelledAt: '_21'
  };
  return mapping;
}

function parseDate(dateStr) {
  if (!dateStr || typeof dateStr !== 'string') return null;
  const cleaned = dateStr.trim();
  const match = cleaned.match(/^(\d{2})-(\d{2})-(\d{2,4})$/);
  if (!match) return null;
  const day = match[1];
  const month = match[2];
  let year = match[3];
  if (year.length === 2) {
    const yearNum = parseInt(year, 10);
    year = yearNum <= 50 ? `20${year}` : `19${year}`;
  }
  return `${year}-${month}-${day}`;
}

function parseDatetime(datetimeStr) {
  if (!datetimeStr || typeof datetimeStr !== 'string') return null;
  const match = datetimeStr.trim().match(/^(\d{2})-(\d{2})-(\d{4})\s(\d{2}):(\d{2}):(\d{2})$/);
  if (!match) return null;
  return `${match[3]}-${match[2]}-${match[1]}T${match[4]}:${match[5]}:${match[6]}`;
}

function parsePrice(priceStr) {
  if (!priceStr || typeof priceStr !== 'string') return null;
  try {
    const cleaned = priceStr.replace(/€/g, '').trim().replace(',', '.');
    const price = parseFloat(cleaned);
    return isNaN(price) ? null : price;
  } catch (error) {
    return null;
  }
}

function getWeekday(dateStr) {
  if (!dateStr) return null;
  try {
    const date = new Date(dateStr + 'T00:00:00Z');
    if (isNaN(date.getTime())) return null;
    const weekdays = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    return weekdays[date.getUTCDay()];
  } catch (error) {
    return null;
  }
}

function calculateNights(arrivalDate, departureDate) {
  if (!arrivalDate || !departureDate) return null;
  try {
    const arrival = new Date(arrivalDate + 'T00:00:00Z');
    const departure = new Date(departureDate + 'T00:00:00Z');
    if (isNaN(arrival.getTime()) || isNaN(departure.getTime())) return null;
    const diffDays = Math.ceil((departure - arrival) / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : null;
  } catch (error) {
    return null;
  }
}

function normalizeChannel(channel) {
  if (!channel || typeof channel !== 'string') return 'Unknown';
  const channelMap = {
    'booking-com': 'Booking.com',
    'booking.com': 'Booking.com',
    'expedia': 'Expedia',
    'hoteliers-com': 'Hoteliers.com',
    'direct-walk-in': 'Walk-in',
    'direct': 'Walk-in',
    'voordeeluitjes-ftc': 'Voordeeluitjes',
    'walk-in': 'Walk-in'
  };
  return channelMap[channel.trim().toLowerCase()] || channel.trim();
}

function normalizeRateCode(rateCode) {
  if (!rateCode || typeof rateCode !== 'string') return 'Unknown';
  return rateCode.trim();
}

function validateDataRow(row, mapping) {
  const result = { isValid: true, errors: [] };
  const createdAt = row[mapping.columns.createdAt];
  const arrival = row[mapping.columns.arrival];
  const departure = row[mapping.columns.departure];

  if (!createdAt) { result.isValid = false; result.errors.push(`Missing creation date`); }
  if (!arrival) { result.isValid = false; result.errors.push(`Missing arrival date`); }
  if (!departure) { result.isValid = false; result.errors.push(`Missing departure date`); }
  if (!result.isValid) return result;

  const datetimePattern = /^\d{2}-\d{2}-\d{4}\s\d{2}:\d{2}:\d{2}$/;
  const datePattern = /^\d{2}-\d{2}-\d{2,4}$/;

  if (!datetimePattern.test(createdAt)) { result.isValid = false; result.errors.push(`Invalid creation datetime`); }
  if (!datePattern.test(arrival)) { result.isValid = false; result.errors.push(`Invalid arrival date`); }
  if (!datePattern.test(departure)) { result.isValid = false; result.errors.push(`Invalid departure date`); }

  return result;
}

function processReservation(row, mapping, rowIndex) {
  const warnings = [];
  const validation = validateDataRow(row, mapping);
  if (!validation.isValid) return null;

  const reservationId = mapping.columns.reservationId && row[mapping.columns.reservationId]
    ? String(row[mapping.columns.reservationId]).trim() : null;

  const createdAt = parseDatetime(row[mapping.columns.createdAt]);
  const arrivalDate = parseDate(row[mapping.columns.arrival]);
  const departureDate = parseDate(row[mapping.columns.departure]);
  const cancelledAt = mapping.columns.cancelledAt && row[mapping.columns.cancelledAt]
    ? parseDatetime(row[mapping.columns.cancelledAt]) : null;

  if (!createdAt) warnings.push(`Failed to parse creation date`);
  if (!arrivalDate) warnings.push(`Failed to parse arrival date`);
  if (!departureDate) warnings.push(`Failed to parse departure date`);

  const averagePrice = mapping.columns.averagePrice && row[mapping.columns.averagePrice]
    ? parsePrice(row[mapping.columns.averagePrice]) : null;
  const totalPrice = mapping.columns.totalPrice && row[mapping.columns.totalPrice]
    ? parsePrice(row[mapping.columns.totalPrice]) : null;

  const nightsFromData = mapping.columns.nights && row[mapping.columns.nights]
    ? parseInt(row[mapping.columns.nights], 10) : null;
  const calculatedNights = calculateNights(arrivalDate, departureDate);
  const nights = nightsFromData !== null ? nightsFromData : calculatedNights;

  const channel = mapping.columns.channel ? normalizeChannel(row[mapping.columns.channel]) : 'Unknown';
  const rateCode = mapping.columns.rateCode ? normalizeRateCode(row[mapping.columns.rateCode]) : 'Unknown';
  const weekdayArrival = getWeekday(arrivalDate);

  const result = {
    reservation_id: reservationId,
    arrival_date: arrivalDate,
    room_nights: nights,
    departure_date: departureDate,
    created_at: createdAt,
    weekday_arrival: weekdayArrival,
    channel: channel,
    rate_code: rateCode
  };

  if (averagePrice !== null) result.average_price = averagePrice;
  if (totalPrice !== null) result.total_price = totalPrice;
  if (cancelledAt) result.cancelled_at = cancelledAt;
  if (warnings.length > 0) result._warnings = warnings;

  return result;
}

// ========== N8N EXECUTION CODE ==========

const items = $input.all();
const rows = items.map(item => item.json);

const hotelNameExtracted = extractHotelName(rows);
const mapping = detectColumnMapping(rows);

const processedReservations = [];
let isFirstDataRow = true;

for (let i = 0; i < rows.length; i++) {
  const processed = processReservation(rows[i], mapping, i);
  if (processed) {
    if (isFirstDataRow) {
      processed.hotelName = hotelNameExtracted;
      isFirstDataRow = false;
    }
    processedReservations.push(processed);
  }
}

const withResId = processedReservations.filter(r => r.reservation_id).length;
const withoutResId = processedReservations.filter(r => !r.reservation_id).length;
const withWarnings = processedReservations.filter(r => r._warnings && r._warnings.length > 0).length;
const skippedRows = rows.length - processedReservations.length;

const warnings = [];
if (!hotelNameExtracted) warnings.push('Hotel name not found in first 3 rows');
if (!mapping.columns.reservationId) warnings.push('Reservation ID column ("Res. #") not detected');
if (mapping.missingColumns.length > 0) warnings.push(`Missing columns: ${mapping.missingColumns.join(', ')}`);
if (mapping.usedFallback) warnings.push('Header row not found - used fallback column positions');
if (withoutResId > 0) warnings.push(`${withoutResId} reservations have no reservation_id`);
if (withWarnings > 0) warnings.push(`${withWarnings} reservations have parsing warnings`);

if (processedReservations.length === 0) {
  return [{
    json: {
      _summary: true,
      status: 'Error',
      message: 'No valid reservations found',
      total_rows: rows.length,
      successfully_processed: 0,
      skipped_rows: skippedRows,
      detection_method: mapping.detectionMethod,
      missing_columns: mapping.missingColumns,
      warnings: warnings
    }
  }];
}

const output = processedReservations.map(reservation => ({ json: reservation }));

output.push({
  json: {
    _summary: true,
    status: warnings.length === 0 ? 'Success' : 'Success with warnings',
    message: `Processed ${processedReservations.length} reservations from ${rows.length} rows`,
    total_rows: rows.length,
    successfully_processed: processedReservations.length,
    skipped_rows: skippedRows,
    with_reservation_id: withResId,
    without_reservation_id: withoutResId,
    with_warnings: withWarnings,
    hotel_name: hotelNameExtracted || 'NOT FOUND',
    detection_method: mapping.detectionMethod,
    missing_columns: mapping.missingColumns,
    warnings: warnings
  }
});

return output;

/**
 * Fact Check Node - Complete verification data for AI fact-checking
 *
 * Combines Data Parser output + Historical Analysis output + Forecast output
 * into one comprehensive fact-check item per forecast day.
 *
 * Place after a Merge node that combines:
 * 1. Data Parser output (parsed input data)
 * 2. Historical Analysis output (baselines, curves, ratios)
 * 3. Forecast Output (actual forecast results)
 *
 * Each output item includes:
 * - All inputs used for that day
 * - Baseline calculation trace (with historical housestate data)
 * - Booking curve trace (with historical reservation data)
 * - Revenue ratio trace
 * - Events affecting the day
 * - Actual forecast output
 * - Verification checks
 *
 * Filter by date to get everything needed for AI to verify one day.
 */

const allItems = $input.all();
const allData = allItems.map(item => item.json);

// Find the different data sources
const dataParserOutput = allData.find(d => d.data && d.data.currentHousestate);
const historicalAnalysisOutput = allData.find(d => d.analysis && d.analysis.weekdayBaselines);
const forecastOutputItems = allData.filter(d => d.Stay_Date !== undefined);

// Validate we have all required inputs
const missingInputs = [];
if (!dataParserOutput) missingInputs.push('Data Parser output');
if (!historicalAnalysisOutput) missingInputs.push('Historical Analysis output');
if (forecastOutputItems.length === 0) missingInputs.push('Forecast output');

if (missingInputs.length > 0) {
  return [{
    json: {
      error: 'Missing required inputs',
      missing: missingInputs,
      hint: 'Merge Data Parser, Historical Analysis, and Forecast Output before this node'
    }
  }];
}

const parsedData = dataParserOutput.data;
const analysis = historicalAnalysisOutput.analysis;

// Extract all data sources
const hotelInfo = parsedData.hotelInfo || {};
const currentHousestate = parsedData.currentHousestate || [];
const historicalHousestate = parsedData.historicalHousestate || [];
const historicalReservations = parsedData.historicalReservations || [];
const events = parsedData.events || [];

const maxRooms = hotelInfo.maxRooms || 100;
const growthTrend = hotelInfo.growthTrend || 1.0;

// Get baselines and curves from analysis
const weekdayBaselines = analysis.weekdayBaselines || {};
const leadtimeCurves = analysis.leadtimeCurves || {};
const revenueRatios = analysis.revenueRatios || {};

// Determine seasonal window
const forecastStartDate = currentHousestate.length > 0
  ? new Date(currentHousestate[0].date)
  : new Date();

const oneYearAgo = new Date(forecastStartDate);
oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);

const windowStart = new Date(oneYearAgo);
windowStart.setDate(windowStart.getDate() - 30);

const windowEnd = new Date(oneYearAgo);
windowEnd.setDate(windowEnd.getDate() + 60);

// Filter historical housestate to seasonal window
const seasonalHousestate = historicalHousestate.filter(day => {
  if (!day.date || day.isOutlier) return false;
  const d = new Date(day.date);
  return d >= windowStart && d <= windowEnd;
});

// Group seasonal housestate by weekday
const housestateByWeekday = {};
seasonalHousestate.forEach(day => {
  const wd = day.weekday;
  if (!housestateByWeekday[wd]) housestateByWeekday[wd] = [];
  housestateByWeekday[wd].push(day);
});

// Filter historical reservations to seasonal window
const seasonalReservations = historicalReservations.filter(res => {
  if (!res.arrivalDate) return false;
  const d = new Date(res.arrivalDate);
  return d >= windowStart && d <= windowEnd;
});

// Group reservations by weekday
const reservationsByWeekday = {};
seasonalReservations.forEach(res => {
  const wd = res.weekdayArrival;
  if (!reservationsByWeekday[wd]) reservationsByWeekday[wd] = [];
  reservationsByWeekday[wd].push(res);
});

const output = [];

// Process each forecast day
forecastOutputItems.forEach((forecastDay, idx) => {
  const dateStr = forecastDay.Stay_Date;
  const weekday = forecastDay.Weekday;
  const daysUntilArrival = forecastDay.Days_Until_Arrival;

  // Find corresponding OTB day
  const otbDay = currentHousestate.find(d => {
    const otbDateStr = new Date(d.date).toISOString().split('T')[0];
    return otbDateStr === dateStr;
  }) || currentHousestate[idx];

  // Get baseline for this weekday
  const baseline = weekdayBaselines[weekday];

  // Get historical housestate days used for this weekday's baseline
  const housestateUsed = housestateByWeekday[weekday] || [];

  // Get booking curve for this weekday
  const curve = leadtimeCurves[weekday] || {};
  const curveKey = `day${daysUntilArrival}`;
  const curvePercentage = curve[curveKey] || 50;

  // Get reservations used for this weekday's booking curve
  const reservationsUsed = reservationsByWeekday[weekday] || [];

  // Calculate leadtime distribution from reservations (for fact-checking curve)
  const reservationsWithLeadtime = reservationsUsed.filter(r => r.leadtime != null);
  const reservationsAtThisLeadtime = reservationsWithLeadtime.filter(r => r.leadtime >= daysUntilArrival);
  const curveFromReservations = reservationsWithLeadtime.length > 0
    ? (reservationsAtThisLeadtime.length / reservationsWithLeadtime.length) * 100
    : null;

  // Events affecting this day
  const targetDate = new Date(dateStr);
  const applicableEvents = events.filter(event => {
    if (!event.startDate || !event.endDate) return false;
    const start = new Date(event.startDate);
    const end = new Date(event.endDate);
    return targetDate >= start && targetDate <= end;
  });

  const totalEventPickup = applicableEvents.reduce((sum, e) => sum + (e.pickupImpact || 0), 0);
  const capacityOverride = applicableEvents.find(e => e.overrideMaxRooms != null && e.overrideMaxRooms > 0)?.overrideMaxRooms || null;
  const effectiveCapacity = capacityOverride || maxRooms;

  // Forecast method
  const forecastMethod = daysUntilArrival > 30 ? 'traditional' : 'curve-based';

  // Build comprehensive fact-check item
  const factCheckItem = {
    // === IDENTIFICATION ===
    date: dateStr,
    weekday: weekday,
    dayIndex: idx + 1,
    daysUntilArrival: daysUntilArrival,
    forecastMethod: forecastMethod,

    // === CONFIG ===
    config: {
      hotelName: hotelInfo.hotelName,
      maxRooms: maxRooms,
      effectiveCapacity: effectiveCapacity,
      growthTrend: growthTrend,
      seasonalWindow: {
        start: windowStart.toISOString().split('T')[0],
        end: windowEnd.toISOString().split('T')[0]
      }
    },

    // === OTB INPUT ===
    otbInput: otbDay ? {
      roomNights: otbDay.roomNights,
      roomRevenue: Math.round(otbDay.roomRevenue * 100) / 100,
      totalRevenue: Math.round(otbDay.totalRevenue * 100) / 100,
      fbRevenue: otbDay.fbRevenue != null ? Math.round(otbDay.fbRevenue * 100) / 100 : null,
      otherRevenue: otbDay.otherRevenue != null ? Math.round(otbDay.otherRevenue * 100) / 100 : null,
      adr: otbDay.roomNights > 0 ? Math.round((otbDay.roomRevenue / otbDay.roomNights) * 100) / 100 : null
    } : { error: 'OTB day not found' },

    // === BASELINE TRACE (from Historical Housestate) ===
    baselineTrace: {
      weekday: weekday,
      calculatedBaseline: baseline ? {
        historicalAvgRoomNights: baseline.historicalAvgRoomNights,
        historicalAvgRoomRevenue: baseline.historicalAvgRoomRevenue,
        historicalAvgTotalRevenue: baseline.historicalAvgTotalRevenue,
        historicalADR: baseline.historicalADR,
        sampleSize: baseline.sampleSize
      } : null,
      withGrowth: baseline ? {
        expectedRoomNights: Math.round(baseline.historicalAvgRoomNights * growthTrend * 100) / 100,
        expectedADR: Math.round(baseline.historicalADR * growthTrend * 100) / 100
      } : null,
      housestateDataUsed: {
        count: housestateUsed.length,
        dates: housestateUsed.slice(0, 5).map(d => new Date(d.date).toISOString().split('T')[0]),
        samples: housestateUsed.slice(0, 5).map(d => ({
          date: new Date(d.date).toISOString().split('T')[0],
          roomNights: d.roomNights,
          roomRevenue: Math.round(d.roomRevenue * 100) / 100,
          adr: d.roomNights > 0 ? Math.round((d.roomRevenue / d.roomNights) * 100) / 100 : null
        })),
        moreAvailable: housestateUsed.length > 5
      }
    },

    // === BOOKING CURVE TRACE (from Historical Reservations) ===
    bookingCurveTrace: forecastMethod === 'curve-based' ? {
      daysUntilArrival: daysUntilArrival,
      curvePercentageUsed: curvePercentage,
      reservationDataUsed: {
        totalReservations: reservationsUsed.length,
        withLeadtimeData: reservationsWithLeadtime.length,
        bookedByThisLeadtime: reservationsAtThisLeadtime.length,
        calculatedPercentage: curveFromReservations != null ? Math.round(curveFromReservations * 100) / 100 : null,
        samples: reservationsWithLeadtime.slice(0, 5).map(r => ({
          arrivalDate: new Date(r.arrivalDate).toISOString().split('T')[0],
          leadtime: r.leadtime,
          roomNights: r.roomNights,
          bookedBeforeThisLeadtime: r.leadtime >= daysUntilArrival
        })),
        moreAvailable: reservationsWithLeadtime.length > 5
      },
      curveCalculation: {
        formula: 'OTB ÷ curvePercentage',
        otb: otbDay?.roomNights || 0,
        percentage: curvePercentage,
        projected: Math.round((otbDay?.roomNights || 0) / (curvePercentage / 100) * 100) / 100
      }
    } : { note: 'Not used for traditional method (> 30 days out)' },

    // === REVENUE RATIO TRACE ===
    revenueRatioTrace: {
      overall: {
        fbRatio: revenueRatios.overall?.fbRatio != null ? Math.round(revenueRatios.overall.fbRatio * 1000) / 1000 : null,
        otherRatio: revenueRatios.overall?.otherRatio != null ? Math.round(revenueRatios.overall.otherRatio * 1000) / 1000 : null,
        totalRatio: revenueRatios.overall?.totalRatio != null ? Math.round(revenueRatios.overall.totalRatio * 1000) / 1000 : null
      },
      weekday: revenueRatios.byWeekday?.[weekday] ? {
        fbRatio: Math.round(revenueRatios.byWeekday[weekday].fbRatio * 1000) / 1000,
        otherRatio: Math.round(revenueRatios.byWeekday[weekday].otherRatio * 1000) / 1000,
        totalRatio: Math.round(revenueRatios.byWeekday[weekday].totalRatio * 1000) / 1000
      } : null
    },

    // === EVENTS ===
    events: applicableEvents.length > 0 ? {
      count: applicableEvents.length,
      totalPickupImpact: totalEventPickup,
      capacityOverride: capacityOverride,
      details: applicableEvents.map(e => ({
        name: e.eventName,
        start: new Date(e.startDate).toISOString().split('T')[0],
        end: new Date(e.endDate).toISOString().split('T')[0],
        pickupImpact: e.pickupImpact,
        overrideMaxRooms: e.overrideMaxRooms
      }))
    } : null,

    // === ACTUAL FORECAST OUTPUT ===
    forecastOutput: {
      roomNightsFinal: forecastDay.Room_Nights_Final,
      pickup: forecastDay.Pickup,
      roomRevenue: forecastDay.Room_Revenue,
      fbRevenue: forecastDay.FB_Revenue,
      otherRevenue: forecastDay.Other_Revenue,
      totalRevenue: forecastDay.Total_Revenue,
      historicalADR: forecastDay.Historical_ADR,
      expectedADR: forecastDay.Expected_ADR,
      otbADR: forecastDay.OTB_ADR,
      occupancyPct: forecastDay.Occupancy_Pct,
      revpar: forecastDay.RevPAR
    },

    // === VERIFICATION CALCULATIONS ===
    verification: {
      // Room nights calculation
      roomNightsCheck: forecastMethod === 'traditional' ? {
        method: 'traditional',
        formula: '(baseline × growth) + eventPickup, capped at capacity',
        baseline: baseline?.historicalAvgRoomNights || 0,
        withGrowth: Math.round((baseline?.historicalAvgRoomNights || 0) * growthTrend * 100) / 100,
        withEvents: Math.round(((baseline?.historicalAvgRoomNights || 0) * growthTrend + totalEventPickup) * 100) / 100,
        capped: Math.min(Math.round(((baseline?.historicalAvgRoomNights || 0) * growthTrend + totalEventPickup) * 100) / 100, effectiveCapacity),
        actual: forecastDay.Room_Nights_Final
      } : {
        method: 'curve-based',
        formula: '(OTB ÷ curvePercentage × growth) + eventPickup, capped at capacity',
        otb: otbDay?.roomNights || 0,
        curvePercentage: curvePercentage,
        projected: Math.round((otbDay?.roomNights || 0) / (curvePercentage / 100) * 100) / 100,
        withGrowth: Math.round((otbDay?.roomNights || 0) / (curvePercentage / 100) * growthTrend * 100) / 100,
        withEvents: Math.round(((otbDay?.roomNights || 0) / (curvePercentage / 100) * growthTrend + totalEventPickup) * 100) / 100,
        capped: Math.min(Math.round(((otbDay?.roomNights || 0) / (curvePercentage / 100) * growthTrend + totalEventPickup) * 100) / 100, effectiveCapacity),
        actual: forecastDay.Room_Nights_Final
      },

      // Pickup calculation
      pickupCheck: {
        formula: 'max(0, forecastedRoomNights - otbRoomNights)',
        forecasted: forecastDay.Room_Nights_Final,
        otb: otbDay?.roomNights || 0,
        expected: Math.max(0, forecastDay.Room_Nights_Final - (otbDay?.roomNights || 0)),
        actual: forecastDay.Pickup
      },

      // Revenue calculation
      revenueCheck: {
        roomRevenueFormula: 'otbRoomRevenue + (pickup × pickupADR)',
        totalRevenueFormula: 'roomRevenue + fbRevenue + otherRevenue',
        fbRevenueFormula: 'roomRevenue × fbRatio',
        components: {
          otbRoomRevenue: otbDay?.roomRevenue || 0,
          pickup: forecastDay.Pickup,
          pickupADR: forecastDay.OTB_ADR || forecastDay.Expected_ADR,
          fbRatio: revenueRatios.overall?.fbRatio || 0,
          otherRatio: revenueRatios.overall?.otherRatio || 0
        }
      }
    }
  };

  output.push(factCheckItem);
});

// Add summary item
output.push({
  date: 'SUMMARY',
  factCheckSummary: {
    totalDays: forecastOutputItems.length,
    dataSourcesUsed: {
      historicalHousestateDays: seasonalHousestate.length,
      historicalReservations: seasonalReservations.length,
      events: events.length
    },
    analysisOutputs: {
      weekdayBaselines: Object.keys(weekdayBaselines).length,
      bookingCurves: Object.keys(leadtimeCurves).length,
      revenueRatios: revenueRatios.overall ? 'available' : 'missing'
    },
    filterInstructions: [
      'Filter date = "YYYY-MM-DD" for specific day',
      'Filter date = "SUMMARY" for this summary'
    ]
  }
});

return output.map(item => ({ json: item }));

/**
 * Validation Node - Checks forecast output integrity and compares to input
 *
 * Outputs array of items with 'category' and 'status' fields for filtering:
 * - category: "integrity", "consistency", "comparison", "business_logic", "summary"
 * - status: "pass", "fail", "warning", "info"
 *
 * Use n8n Filter node:
 * - Filter by status = "fail" to see only failures
 * - Filter by category = "comparison" to see input vs output checks
 *
 * Expected inputs (via Merge node):
 * - Forecast output items (from Output Formatter)
 * - Input summary items (from Input Summary node) - optional
 */

const allItems = $input.all();
const allData = allItems.map(item => item.json);

const checks = [];

// Separate forecast data from input summary
const forecastData = allData.filter(d => d.Stay_Date !== undefined);
const inputSummary = allData.filter(d => d.type !== undefined);

// Extract input summary by type
const hotelInfo = inputSummary.find(d => d.type === 'hotel_info');
const events = inputSummary.filter(d => d.type === 'event');
const otbDays = inputSummary.filter(d => d.type === 'otb_day');
const summary = inputSummary.find(d => d.type === 'summary');

// ============ INTEGRITY CHECKS ============

// Check 1: Forecast has data
checks.push({
  category: 'integrity',
  checkId: 'forecast_count',
  status: forecastData.length >= 85 ? 'pass' : 'fail',
  message: `Forecast contains ${forecastData.length} days (expected ~90)`,
  expected: '85-95',
  actual: forecastData.length
});

// Check 2: No null Stay_Date
const nullDates = forecastData.filter(d => !d.Stay_Date);
checks.push({
  category: 'integrity',
  checkId: 'null_dates',
  status: nullDates.length === 0 ? 'pass' : 'fail',
  message: nullDates.length === 0 ? 'All dates present' : `${nullDates.length} rows have null Stay_Date`,
  expected: 0,
  actual: nullDates.length
});

// Check 3: No negative Room_Nights_Final
const negativeRN = forecastData.filter(d => d.Room_Nights_Final < 0);
checks.push({
  category: 'integrity',
  checkId: 'negative_room_nights',
  status: negativeRN.length === 0 ? 'pass' : 'fail',
  message: negativeRN.length === 0 ? 'No negative room nights' : `${negativeRN.length} rows have negative Room_Nights_Final`,
  expected: 0,
  actual: negativeRN.length,
  flaggedDates: negativeRN.slice(0, 5).map(d => d.Stay_Date)
});

// Check 4: No negative Pickup
const negativePickup = forecastData.filter(d => d.Pickup < 0);
checks.push({
  category: 'integrity',
  checkId: 'negative_pickup',
  status: negativePickup.length === 0 ? 'pass' : 'fail',
  message: negativePickup.length === 0 ? 'No negative pickup' : `${negativePickup.length} rows have negative Pickup`,
  expected: 0,
  actual: negativePickup.length,
  flaggedDates: negativePickup.slice(0, 5).map(d => d.Stay_Date)
});

// Check 5: No negative revenues
const negativeRevenue = forecastData.filter(d =>
  d.Room_Revenue < 0 || d.Total_Revenue < 0 || (d.FB_Revenue != null && d.FB_Revenue < 0)
);
checks.push({
  category: 'integrity',
  checkId: 'negative_revenue',
  status: negativeRevenue.length === 0 ? 'pass' : 'fail',
  message: negativeRevenue.length === 0 ? 'No negative revenue' : `${negativeRevenue.length} rows have negative revenue`,
  expected: 0,
  actual: negativeRevenue.length,
  flaggedDates: negativeRevenue.slice(0, 5).map(d => d.Stay_Date)
});

// Check 6: Occupancy in valid range (0-100%)
const invalidOccupancy = forecastData.filter(d =>
  d.Occupancy_Pct < 0 || d.Occupancy_Pct > 100
);
checks.push({
  category: 'integrity',
  checkId: 'occupancy_range',
  status: invalidOccupancy.length === 0 ? 'pass' : 'fail',
  message: invalidOccupancy.length === 0 ? 'All occupancy values 0-100%' : `${invalidOccupancy.length} rows have invalid occupancy`,
  expected: '0-100%',
  actual: invalidOccupancy.length > 0 ? `${invalidOccupancy.length} invalid` : 'all valid',
  flaggedDates: invalidOccupancy.slice(0, 5).map(d => ({ date: d.Stay_Date, value: d.Occupancy_Pct }))
});

// ============ CONSISTENCY CHECKS ============

// Check 7: Total Revenue = Room + FB + Other (within tolerance)
const revenueMismatch = forecastData.filter(d => {
  const calculated = (d.Room_Revenue || 0) + (d.FB_Revenue || 0) + (d.Other_Revenue || 0);
  const diff = Math.abs(calculated - (d.Total_Revenue || 0));
  return diff > 0.02; // 2 cent tolerance
});
checks.push({
  category: 'consistency',
  checkId: 'revenue_sum',
  status: revenueMismatch.length === 0 ? 'pass' : 'fail',
  message: revenueMismatch.length === 0 ? 'Revenue sums match' : `${revenueMismatch.length} rows have revenue sum mismatch`,
  expected: 'Room + FB + Other = Total',
  actual: revenueMismatch.length > 0 ? `${revenueMismatch.length} mismatches` : 'all match',
  flaggedDates: revenueMismatch.slice(0, 5).map(d => ({
    date: d.Stay_Date,
    room: d.Room_Revenue,
    fb: d.FB_Revenue,
    other: d.Other_Revenue,
    total: d.Total_Revenue,
    calculated: (d.Room_Revenue || 0) + (d.FB_Revenue || 0) + (d.Other_Revenue || 0)
  }))
});

// Check 8: OTB Room Nights <= Forecast Room Nights
const otbExceedsForecast = forecastData.filter(d =>
  d.OTB_Room_Nights > d.Room_Nights_Final + 0.01
);
checks.push({
  category: 'consistency',
  checkId: 'otb_not_exceeds_forecast',
  status: otbExceedsForecast.length === 0 ? 'pass' : 'warning',
  message: otbExceedsForecast.length === 0 ? 'OTB never exceeds forecast' : `${otbExceedsForecast.length} rows where OTB > Forecast (curve extrapolation)`,
  expected: 'OTB <= Forecast',
  actual: otbExceedsForecast.length > 0 ? `${otbExceedsForecast.length} exceptions` : 'all valid',
  flaggedDates: otbExceedsForecast.slice(0, 5).map(d => ({
    date: d.Stay_Date,
    otb: d.OTB_Room_Nights,
    forecast: d.Room_Nights_Final
  }))
});

// Check 9: Pickup = Forecast - OTB
const pickupMismatch = forecastData.filter(d => {
  const expectedPickup = Math.max(0, d.Room_Nights_Final - d.OTB_Room_Nights);
  const diff = Math.abs(d.Pickup - expectedPickup);
  return diff > 0.01;
});
checks.push({
  category: 'consistency',
  checkId: 'pickup_calculation',
  status: pickupMismatch.length === 0 ? 'pass' : 'fail',
  message: pickupMismatch.length === 0 ? 'Pickup calculation correct' : `${pickupMismatch.length} rows have incorrect pickup`,
  expected: 'Pickup = max(0, Forecast - OTB)',
  actual: pickupMismatch.length > 0 ? `${pickupMismatch.length} mismatches` : 'all correct',
  flaggedDates: pickupMismatch.slice(0, 5).map(d => ({
    date: d.Stay_Date,
    pickup: d.Pickup,
    forecast: d.Room_Nights_Final,
    otb: d.OTB_Room_Nights,
    expected: Math.max(0, d.Room_Nights_Final - d.OTB_Room_Nights)
  }))
});

// ============ BUSINESS LOGIC CHECKS ============

// Check 10: Expected ADR differs from Historical when growth != 1.0
if (hotelInfo && hotelInfo.growthTrend !== 1.0) {
  const adrSame = forecastData.filter(d =>
    d.Historical_ADR > 0 &&
    Math.abs(d.Expected_ADR - d.Historical_ADR) < 0.01
  );
  checks.push({
    category: 'business_logic',
    checkId: 'growth_applied_to_adr',
    status: adrSame.length === 0 ? 'pass' : 'warning',
    message: adrSame.length === 0 ? 'Growth trend applied to ADR' : `${adrSame.length} rows where Expected ADR = Historical ADR (growth not visible)`,
    expected: `Expected ADR = Historical ADR * ${hotelInfo.growthTrend}`,
    actual: adrSame.length > 0 ? `${adrSame.length} unchanged` : 'growth applied'
  });
}

// Check 11: Method switch at day 30 (Days_Until_Arrival)
const day30 = forecastData.find(d => d.Days_Until_Arrival === 30);
const day31 = forecastData.find(d => d.Days_Until_Arrival === 31);
if (day30 && day31) {
  checks.push({
    category: 'business_logic',
    checkId: 'method_switch_boundary',
    status: 'info',
    message: 'Day 30/31 boundary samples for manual verification',
    day30: {
      date: day30.Stay_Date,
      daysUntil: day30.Days_Until_Arrival,
      roomNights: day30.Room_Nights_Final,
      otb: day30.OTB_Room_Nights
    },
    day31: {
      date: day31.Stay_Date,
      daysUntil: day31.Days_Until_Arrival,
      roomNights: day31.Room_Nights_Final,
      otb: day31.OTB_Room_Nights
    }
  });
}

// Check 12: Capacity respected (if hotel info available)
if (hotelInfo && hotelInfo.maxRooms > 0) {
  const overCapacity = forecastData.filter(d => d.Room_Nights_Final > hotelInfo.maxRooms);
  checks.push({
    category: 'business_logic',
    checkId: 'capacity_respected',
    status: overCapacity.length === 0 ? 'pass' : 'fail',
    message: overCapacity.length === 0 ? 'Capacity respected' : `${overCapacity.length} rows exceed max rooms (${hotelInfo.maxRooms})`,
    expected: `<= ${hotelInfo.maxRooms}`,
    actual: overCapacity.length > 0 ? `${overCapacity.length} exceeded` : 'all within capacity',
    flaggedDates: overCapacity.slice(0, 5).map(d => ({
      date: d.Stay_Date,
      roomNights: d.Room_Nights_Final
    }))
  });
}

// ============ COMPARISON CHECKS (if input summary available) ============

if (otbDays.length > 0) {
  // Check 13: OTB data matches between input and output
  let otbMatches = 0;
  let otbMismatches = [];

  otbDays.forEach(inputDay => {
    const outputDay = forecastData.find(d => d.Stay_Date === inputDay.date);
    if (outputDay) {
      const inputOTB = inputDay.otbRoomNights;
      const outputOTB = outputDay.OTB_Room_Nights;
      const diff = Math.abs(inputOTB - outputOTB);
      if (diff < 0.01) {
        otbMatches++;
      } else {
        otbMismatches.push({
          date: inputDay.date,
          inputOTB: inputOTB,
          outputOTB: outputOTB,
          diff: diff
        });
      }
    }
  });

  checks.push({
    category: 'comparison',
    checkId: 'otb_input_vs_output',
    status: otbMismatches.length === 0 ? 'pass' : 'fail',
    message: otbMismatches.length === 0 ? 'OTB data matches input' : `${otbMismatches.length} days have OTB mismatch`,
    expected: 'Input OTB = Output OTB',
    actual: `${otbMatches} match, ${otbMismatches.length} mismatch`,
    flaggedDates: otbMismatches.slice(0, 5)
  });
}

// Check 14: Events applied on correct dates
if (events.length > 0) {
  events.forEach(event => {
    // Find forecast days within event date range
    const eventDays = forecastData.filter(d => {
      const stayDate = new Date(d.Stay_Date);
      const startDate = new Date(event.startDate);
      const endDate = new Date(event.endDate);
      return stayDate >= startDate && stayDate <= endDate;
    });

    if (eventDays.length > 0 && event.pickupImpact !== 0) {
      checks.push({
        category: 'comparison',
        checkId: `event_${event.eventIndex}_applied`,
        status: 'info',
        message: `Event "${event.eventName}" covers ${eventDays.length} forecast days`,
        event: {
          name: event.eventName,
          start: event.startDate,
          end: event.endDate,
          pickupImpact: event.pickupImpact,
          capacityOverride: event.overrideMaxRooms
        },
        sampleDays: eventDays.slice(0, 3).map(d => ({
          date: d.Stay_Date,
          roomNights: d.Room_Nights_Final,
          pickup: d.Pickup,
          otb: d.OTB_Room_Nights
        }))
      });
    }
  });
}

// ============ SUMMARY ============

const passCount = checks.filter(c => c.status === 'pass').length;
const failCount = checks.filter(c => c.status === 'fail').length;
const warningCount = checks.filter(c => c.status === 'warning').length;
const infoCount = checks.filter(c => c.status === 'info').length;

// Stats on forecast data
const roomNightsArr = forecastData.map(d => d.Room_Nights_Final);
const revenueArr = forecastData.map(d => d.Total_Revenue);
const adrArr = forecastData.filter(d => d.Expected_ADR > 0).map(d => d.Expected_ADR);
const occupancyArr = forecastData.map(d => d.Occupancy_Pct);

const calcStats = (arr) => ({
  min: Math.min(...arr),
  max: Math.max(...arr),
  avg: Math.round((arr.reduce((a, b) => a + b, 0) / arr.length) * 100) / 100
});

checks.push({
  category: 'summary',
  checkId: 'validation_summary',
  status: failCount === 0 ? 'pass' : 'fail',
  message: failCount === 0 ? 'All checks passed' : `${failCount} checks failed`,
  results: {
    pass: passCount,
    fail: failCount,
    warning: warningCount,
    info: infoCount,
    total: checks.length
  },
  forecastStats: {
    dayCount: forecastData.length,
    roomNights: calcStats(roomNightsArr),
    totalRevenue: calcStats(revenueArr),
    expectedADR: adrArr.length > 0 ? calcStats(adrArr) : null,
    occupancy: calcStats(occupancyArr)
  },
  inputAvailable: {
    hotelInfo: !!hotelInfo,
    events: events.length,
    otbDays: otbDays.length
  }
});

// Return as array of items for n8n
return checks.map(item => ({ json: item }));

// Hotel Data Processing Script for n8n
// Processes Dutch hotel occupancy data and converts to clean JSON
// Error handling & observability aligned with README style (pared down):
// summary fields: header_rows_skipped, non_data_rows_skipped, missing_columns,
// used_fallback, successfully_processed, failed_validation, errors_count.
//
// V2.1 UPDATE (Feb 2026): Support for new Excel export format where:
// - Column keys changed from "_N" and "Periode:" to "__EMPTY_N"
// - Date is now SPLIT across two columns (weekday + date separately)
// - Hotel name now appears in cell values instead of column keys
// - Page break rows are inserted in the data
// - Backwards compatible with old format

// -------------------- Constants & Utilities --------------------

const WEEKDAY_MAP = {
  ma: 'Monday',
  di: 'Tuesday',
  wo: 'Wednesday',
  do: 'Thursday',
  vr: 'Friday',
  za: 'Saturday',
  zo: 'Sunday',
};

// Hotel names to search for (case-insensitive contains match)
const HOTEL_NAMES = [
  'de Hoeve van Nunspeet',
  // Placeholder for 19 other hotel names - to be added later
  'andere klant 1',
  'andere klant 2',
  'andere klant 3',
  'andere klant 4',
  'andere klant 5',
  'andere klant 6',
  'andere klant 7',
  'andere klant 8',
  'andere klant 9',
  'andere klant 10',
  'andere klant 11',
  'andere klant 12',
  'andere klant 13',
  'andere klant 14',
  'andere klant 15',
  'andere klant 16',
  'andere klant 17',
  'andere klant 18',
  'andere klant 19',
];

// tolerant: optional comma, flexible spaces, strict DD-MM-YYYY (OLD FORMAT - combined)
const DATE_PATTERN = /^(ma|di|wo|do|vr|za|zo),?\s+\d{2}-\d{2}-\d{4}$/i;

// NEW FORMAT: weekday only pattern (e.g., "wo," or "ma,")
const WEEKDAY_ONLY_PATTERN = /^(ma|di|wo|do|vr|za|zo),?$/i;

// NEW FORMAT: date only pattern (e.g., "01-01-2025")
const DATE_ONLY_PATTERN = /^\d{2}-\d{2}-\d{4}$/;

function isString(v) { return typeof v === 'string'; }

// Detect format type based on column keys
function detectFormat(rows) {
  for (let i = 0; i < Math.min(10, rows.length); i++) {
    const keys = Object.keys(rows[i] || {});
    if (keys.some(k => k.startsWith('__EMPTY_'))) return 'new';
    if (keys.some(k => k === 'Periode:' || k.match(/^_\d+$/))) return 'old';
  }
  return 'unknown';
}

// OLD FORMAT: date combined in one cell like "ma, 01-09-2025"
function isDateRowOld(cellValue) {
  if (!cellValue || !isString(cellValue)) return false;
  return DATE_PATTERN.test(cellValue.trim());
}

// NEW FORMAT: check if row has weekday in one column and date in another
function isDateRowNew(row) {
  // Look for weekday pattern in __EMPTY_4 and date pattern in __EMPTY_5
  const weekdayCell = row['__EMPTY_4'];
  const dateCell = row['__EMPTY_5'];

  if (!weekdayCell || !dateCell) return false;
  if (!isString(weekdayCell) || !isString(dateCell)) return false;

  return WEEKDAY_ONLY_PATTERN.test(weekdayCell.trim()) && DATE_ONLY_PATTERN.test(dateCell.trim());
}

// Check if row is a date row (either format)
function isDateRow(row, format, dateColumnKey) {
  if (format === 'new') {
    return isDateRowNew(row);
  } else {
    const cellValue = row[dateColumnKey];
    return isDateRowOld(cellValue);
  }
}

function extractWeekday(datumStr) {
  if (!datumStr || !isString(datumStr)) return 'Unknown';
  const head = datumStr.split(',')[0].trim().toLowerCase(); // supports "ma, ..." and "ma  ..." and "ma,"
  const abbr = head.split(/\s+/)[0];
  return WEEKDAY_MAP[abbr] || 'Unknown';
}

function parseDateToISO(datumStr) {
  if (!datumStr || !isString(datumStr)) return null;
  const m = datumStr.match(/\b(\d{2})-(\d{2})-(\d{4})\b/);
  if (!m) return null;
  const [_, dd, MM, yyyy] = m;
  return `${yyyy}-${MM}-${dd}`;
}

// Check if row is a page break / metadata row (NEW FORMAT)
function isPageBreakRow(row) {
  const keys = Object.keys(row);
  // Page break rows have patterns like "User:", "Print date:", "Page"
  for (const key of keys) {
    const val = row[key];
    if (isString(val)) {
      const lower = val.toLowerCase();
      if (lower.includes('user:') || lower.includes('print date') || lower.match(/page\s+\d+/i)) {
        return true;
      }
    }
  }
  return false;
}

// Check if row is a repeated header/title row mid-document (NEW FORMAT)
function isRepeatedHeaderRow(row) {
  const values = Object.values(row).filter(v => isString(v) && v.trim());
  // Repeated header rows typically have "Hotelstatus" or hotel name only
  if (values.length <= 2) {
    const joined = values.join(' ').toLowerCase();
    if (joined.includes('hotelstatus') || joined.includes('hotel de hoeve')) {
      return true;
    }
  }
  return false;
}

function toNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number') return isFinite(value) ? value : null;
  if (typeof value === 'string') {
    const cleaned = value
      .replace(/\s|\u00A0/g, '')
      .replace(/[€$]/g, '')
      .replace(/%/g, '')
      .replace(/,/g, '.') // treat comma as decimal
      .replace(/[^\d.\-]/g, '');
    const num = parseFloat(cleaned);
    return isNaN(num) ? null : num;
  }
  return null;
}

// -------------------- Hotel Name Extraction --------------------

/**
 * Extracts hotel name from first 3 rows by searching in both keys and values
 * Uses contains logic (case-insensitive) to find hotel name
 * Returns the clean hotel name from HOTEL_NAMES array or "error" if not found
 */
function extractHotelName(rows) {
  const searchRows = rows.slice(0, Math.min(3, rows.length));

  // Loop through each hotel name in the array
  for (const hotelName of HOTEL_NAMES) {
    const normalizedHotelName = hotelName.toLowerCase();

    // Search in all rows
    for (const row of searchRows) {
      // Search in column keys (property names)
      for (const key of Object.keys(row)) {
        if (!isString(key)) continue;
        const normalizedKey = key.trim().toLowerCase();

        if (normalizedKey.includes(normalizedHotelName)) {
          return hotelName; // return clean name from array
        }
      }

      // Search in values
      for (const value of Object.values(row)) {
        if (!isString(value)) continue;
        const normalizedValue = value.trim().toLowerCase();

        if (normalizedValue.includes(normalizedHotelName)) {
          return hotelName; // return clean name from array
        }
      }
    }
  }

  return 'error'; // no match found
}

// -------------------- Header Detection (improved) --------------------

// Normalize header labels: lowercase, trim, collapse spaces, remove punctuation & NBSP
function normalizeHeaderLabel(val) {
  if (!isString(val)) return '';
  return val
    .replace(/\u00A0/g, ' ')           // NBSP -> space
    .toLowerCase()
    .trim()
    .replace(/[.,:;]+/g, '')           // strip common punctuation
    .replace(/\s+/g, ' ');             // collapse spaces
}

/**
 * Improved header detection (supports both OLD and NEW formats):
 *
 * OLD FORMAT: row["Periode:"] == "Datum" with "bezet", "accom", "totaal" in values
 * NEW FORMAT: row["__EMPTY_3"] == "Datum" with "bezet", "accom", "totaal" in values
 *
 * Fallback to heuristic scoring if strict check fails.
 */
function findHeaderRow(rows, format) {
  // Strategy 1: strict anchored detection
  for (let i = 0; i < Math.min(rows.length, 60); i++) {
    const row = rows[i] || {};

    // Check for "Datum" in the appropriate column based on format
    let normDatum = '';
    if (format === 'new') {
      // NEW FORMAT: check __EMPTY_3 for "Datum"
      normDatum = normalizeHeaderLabel(row['__EMPTY_3']);
    } else {
      // OLD FORMAT: check "Periode:" for "Datum"
      normDatum = normalizeHeaderLabel(row['Periode:']);
    }

    if (normDatum === 'datum') {
      const values = Object.values(row).map(normalizeHeaderLabel);
      let scoreTokens = 0;
      if (values.some(v => v === 'bezet')) scoreTokens++;
      if (values.some(v => v === 'totaal')) scoreTokens++;
      if (values.some(v => v === 'accom' || v.startsWith('accom'))) scoreTokens++;
      if (scoreTokens >= 2) {
        return { row, index: i, format };
      }
    }
  }

  // Strategy 2: heuristic (legacy) if the anchored search fails
  let best = null;
  for (let i = 0; i < Math.min(rows.length, 20); i++) {
    const row = rows[i];
    const entries = Object.entries(row);
    let score = 0;
    for (const [, v] of entries) {
      const s = normalizeHeaderLabel(v);
      if (!s) continue;
      if (s.includes('datum')) score += 2;
      if (s.includes('bezet')) score += 2;
      if (s.includes('accom')) score += 2;
      if (s.includes('totaal')) score += 2;
    }
    if (score >= 4) { // at least two signals
      best = { row, index: i, format };
      break;
    }
  }
  return best;
}

function createColumnMapping(headerRow, format) {
  const mapping = { format };

  for (const [key, value] of Object.entries(headerRow)) {
    const s = normalizeHeaderLabel(value);
    if (!s) continue;

    // Prefer exact tokens
    if (s === 'datum') {
      mapping.date = key;
      continue;
    }
    if (s === 'bezet') {
      mapping.roomNights = key;
      continue;
    }
    if (s === 'totaal') {
      mapping.totalRevenue = key;
      continue;
    }
    // Accept common variant for accom
    if (s === 'accom' || s.startsWith('accom')) {
      mapping.roomRevenue = key;
      continue;
    }
    // F&B Revenue detection
    if (s === 'f&b' || s === 'fb' || s === 'f & b') {
      mapping.fbRevenue = key;
      continue;
    }
    // Other/Extras Revenue detection
    if (s === 'extras' || s === 'other' || s === 'overig') {
      mapping.otherRevenue = key;
      continue;
    }
  }

  // NEW FORMAT: mark that date is split across two columns
  if (format === 'new') {
    mapping.splitDate = true;
    mapping.weekdayCol = '__EMPTY_4';
    mapping.dateCol = '__EMPTY_5';

    // NEW FORMAT FIX: Header columns for some fields are offset from data columns
    // "Bezet" header is at __EMPTY_14 but data is at __EMPTY_15
    // Apply +1 offset for roomNights if detected from header
    if (mapping.roomNights && mapping.roomNights.startsWith('__EMPTY_')) {
      const colNum = parseInt(mapping.roomNights.replace('__EMPTY_', ''), 10);
      if (!isNaN(colNum) && colNum === 14) {
        mapping.roomNights = '__EMPTY_15';
      }
    }
  }

  return mapping;
}

// Provide fallback mapping if headers missing
function withFallback(mapping, format) {
  const m = { ...mapping };

  if (format === 'new') {
    // NEW FORMAT fallback columns (observed in new sample)
    if (!m.date) m.date = '__EMPTY_3';
    if (!m.roomNights) m.roomNights = '__EMPTY_15';  // "Bezet" value column (note: may be string)
    if (!m.roomRevenue) m.roomRevenue = '__EMPTY_54';
    if (!m.fbRevenue) m.fbRevenue = '__EMPTY_57';
    if (!m.otherRevenue) m.otherRevenue = '__EMPTY_61';
    if (!m.totalRevenue) m.totalRevenue = '__EMPTY_63';
    m.splitDate = true;
    m.weekdayCol = '__EMPTY_4';
    m.dateCol = '__EMPTY_5';
  } else {
    // OLD FORMAT fallback columns
    if (!m.date) m.date = 'Periode:';       // dataset uses this as the date column key
    if (!m.roomNights) m.roomNights = '_4'; // observed in sample
    if (!m.roomRevenue) m.roomRevenue = '_34';
    if (!m.fbRevenue) m.fbRevenue = '_35';           // F&B column
    if (!m.otherRevenue) m.otherRevenue = '_38';     // Extras/Other column
    if (!m.totalRevenue) m.totalRevenue = '_40';
  }

  return m;
}

function computeMissingColumns(mapping) {
  const missing = [];
  if (!mapping.date) missing.push('date');
  if (!mapping.roomNights) missing.push('roomNights');
  if (!mapping.roomRevenue) missing.push('roomRevenue');
  if (!mapping.fbRevenue) missing.push('fbRevenue');
  if (!mapping.otherRevenue) missing.push('otherRevenue');
  if (!mapping.totalRevenue) missing.push('totalRevenue');
  return missing;
}

// -------------------- Row Processing --------------------

function processRowObject(rowObj, mapping, format) {
  // NEW FORMAT: Skip page break and repeated header rows
  if (format === 'new') {
    if (isPageBreakRow(rowObj)) return { kind: 'skip' };
    if (isRepeatedHeaderRow(rowObj)) return { kind: 'skip' };
  }

  // Handle date extraction based on format
  let rawDateCell, weekdayStr, dateStr;

  if (mapping.splitDate) {
    // NEW FORMAT: date split across two columns
    weekdayStr = rowObj[mapping.weekdayCol];
    dateStr = rowObj[mapping.dateCol];

    if (!weekdayStr && !dateStr) return { kind: 'skip' };

    // Check if this is a valid data row
    if (!isString(weekdayStr) || !isString(dateStr)) return { kind: 'skip' };

    weekdayStr = weekdayStr.trim();
    dateStr = dateStr.trim();

    // Skip non-data markers
    const NON_DATA_MARKERS = new Set([
      'datum', 'summary', 'type', 'revenue', 'ooo rooms', 'pseudorooms',
      'state', 'soort tarief', 'totaal', 'systeemdatum:', 'kamers', 'bedden',
      'aankomsten', 'vertrekkers', 'inhuis', 'januari', 'februari', 'maart',
      'april', 'mei', 'juni', 'juli', 'augustus', 'september', 'oktober',
      'november', 'december', 'hotelstatus'
    ]);

    const normalizedWeekday = normalizeHeaderLabel(weekdayStr);
    const normalizedDate = normalizeHeaderLabel(dateStr);
    if (NON_DATA_MARKERS.has(normalizedWeekday) || NON_DATA_MARKERS.has(normalizedDate)) {
      return { kind: 'skip' };
    }

    // Check for valid weekday + date pattern
    if (!WEEKDAY_ONLY_PATTERN.test(weekdayStr) || !DATE_ONLY_PATTERN.test(dateStr)) {
      // If it has a date-like pattern but invalid, it's an error
      if (/\d{2}-\d{2}-\d{4}/.test(dateStr)) {
        return {
          kind: 'error',
          error: `Invalid date pattern in new format: weekday="${weekdayStr}", date="${dateStr}"`,
        };
      }
      return { kind: 'skip' };
    }

    // Combine for compatibility with existing parsing
    rawDateCell = `${weekdayStr} ${dateStr}`;
  } else {
    // OLD FORMAT: date in single column
    rawDateCell = rowObj[mapping.date];
    if (!rawDateCell || !isString(rawDateCell)) return { kind: 'skip' };
    rawDateCell = rawDateCell.trim();

    // Common non-data lines to skip (do not treat as errors)
    const NON_DATA_MARKERS = new Set([
      'summary', 'type', 'revenue', 'ooo rooms', 'pseudorooms',
      'state', 'soort tarief', 'totaal', 'systeemdatum:'
    ]);
    if (NON_DATA_MARKERS.has(normalizeHeaderLabel(rawDateCell))) return { kind: 'skip' };

    // Must be a date row
    if (!isDateRowOld(rawDateCell)) {
      // Heuristic: contains dd-mm-yyyy somewhere but weekday missing/malformed -> error
      const hasDate = /\b\d{2}-\d{2}-\d{4}\b/.test(rawDateCell);
      if (hasDate) {
        return {
          kind: 'error',
          error: `Invalid date pattern: "${rawDateCell}" (expected "ma|di|wo|do|vr|za|zo, DD-MM-YYYY")`,
        };
      }
      return { kind: 'skip' };
    }
  }

  const isoDate = parseDateToISO(rawDateCell);
  if (!isoDate) {
    return {
      kind: 'error',
      error: `Failed to parse date from "${rawDateCell}" (expected DD-MM-YYYY)`,
    };
  }

  const englishWeekday = extractWeekday(rawDateCell);

  // Parse numeric fields (warnings kept minimal; non-numeric => null)
  // Note: NEW FORMAT may have string numbers like "33" - toNumber handles this
  const rn = toNumber(rowObj[mapping.roomNights]);
  const accom = toNumber(rowObj[mapping.roomRevenue]);
  const fb = toNumber(rowObj[mapping.fbRevenue]);
  const other = toNumber(rowObj[mapping.otherRevenue]);
  const total = toNumber(rowObj[mapping.totalRevenue]);

  const out = {
    Date: isoDate,
    Weekday: englishWeekday,
    RoomNights: rn,
    RoomRevenue: accom,
    FB_Revenue: fb,
    OtherRevenue: other,
    TotalRevenue: total,
  };

  // Validation warnings
  const warnings = [];

  // Check: TotalRevenue < RoomRevenue (legacy check)
  if (total != null && accom != null && total < accom) {
    warnings.push(`Mismatch: TotalRevenue (${total}) < RoomRevenue (${accom})`);
  }

  // Check: Sum validation (RoomRevenue + FB_Revenue + OtherRevenue should equal TotalRevenue)
  if (accom != null && fb != null && other != null && total != null) {
    const calculatedSum = accom + fb + other;
    const tolerance = 0.01; // Allow 1 cent tolerance for floating point
    const difference = Math.abs(calculatedSum - total);
    if (difference > tolerance) {
      warnings.push(`Revenue sum mismatch: RoomRevenue (${accom.toFixed(2)}) + FB_Revenue (${fb.toFixed(2)}) + OtherRevenue (${other.toFixed(2)}) = ${calculatedSum.toFixed(2)}, but TotalRevenue = ${total.toFixed(2)} (diff: ${difference.toFixed(2)})`);
    }
  }

  if (warnings.length) out._warnings = warnings;

  return { kind: 'ok', value: out };
}

// -------------------- Main Processing --------------------

const items = $input.all();
const allResults = [];
let totalRows = 0;
let headerRowsSkipped = 0;
let nonDataRowsSkipped = 0;
let successfullyProcessed = 0;
let failedValidation = 0;

const failedRows = []; // collected row-level errors
let usedFallbackAny = false;
const aggMissing = [];
let hotelNameExtracted = null; // track extracted hotel name
let isFirstDataRow = true; // flag to add hotelName to first data row only

// Track column detection results for testing/debugging
let columnDetectionLog = [];
let detectedFormat = 'unknown';

for (const item of items) {
  let rows;
  const inputData = item.json;
  if (Array.isArray(inputData)) rows = inputData;
  else if (inputData && typeof inputData === 'object') rows = [inputData];
  else rows = [];

  totalRows += rows.length;

  // Detect format (OLD vs NEW)
  if (detectedFormat === 'unknown' && rows.length > 0) {
    detectedFormat = detectFormat(rows);
  }

  // Extract hotel name from first rows (only once)
  if (hotelNameExtracted === null && rows.length > 0) {
    hotelNameExtracted = extractHotelName(rows);
  }

  // Header detection (improved) - pass format
  const headerInfo = findHeaderRow(rows, detectedFormat);
  let mapping = {};
  let usedFallback = false;

  if (headerInfo) {
    mapping = createColumnMapping(headerInfo.row, detectedFormat);
    headerRowsSkipped += (headerInfo.index + 1); // start after header

    // Log detected columns for debugging
    columnDetectionLog.push({
      format: detectedFormat,
      headerRowIndex: headerInfo.index,
      detectedMappings: { ...mapping },
      headerRowValues: Object.entries(headerInfo.row)
        .filter(([k, v]) => v && isString(v) && v.trim())
        .map(([k, v]) => ({ key: k, value: v }))
    });
  }

  // If some are missing, apply fallback
  const preFallbackMissing = computeMissingColumns(mapping);
  if (preFallbackMissing.length) {
    mapping = withFallback(mapping, detectedFormat);
    usedFallback = true;
  }

  const missingColumnsAfter = computeMissingColumns(mapping);
  for (const k of missingColumnsAfter) if (!aggMissing.includes(k)) aggMissing.push(k);
  if (usedFallback) usedFallbackAny = true;

  // Critical error: no data or still no date column
  if (rows.length === 0) {
    return [
      {
        json: {
          success: false,
          message: 'No occupancy data found. Please provide an array of row objects.',
        },
      },
    ];
  }
  if (missingColumnsAfter.includes('date') && !mapping.splitDate) {
    return [
      {
        json: {
          success: false,
          message:
            'CRITICAL ERROR: Cannot process data - missing required columns.\n' +
            'Required column: Datum (date column with weekday + DD-MM-YYYY).',
        },
      },
    ];
  }

  // Start processing after header row if present
  const startIndex = headerInfo ? headerInfo.index + 1 : 0;

  for (let i = startIndex; i < rows.length; i++) {
    const rowObj = rows[i];
    const res = processRowObject(rowObj, mapping, detectedFormat);

    if (res.kind === 'ok') {
      // Add hotelName to first data row only
      if (isFirstDataRow) {
        res.value.hotelName = hotelNameExtracted;
        isFirstDataRow = false;
      }

      allResults.push({ json: res.value });
      successfullyProcessed += 1;
    } else if (res.kind === 'error') {
      failedValidation += 1;
      failedRows.push({
        error: true,
        row_index: i,
        validation_errors: [res.error],
        raw_data: rowObj,
      });
    } else {
      nonDataRowsSkipped += 1; // kind === 'skip'
    }
  }
}

// If everything failed (no successes) and we had row-level errors -> Critical style
if (successfullyProcessed === 0 && failedValidation > 0) {
  return [
    {
      json: {
        success: false,
        message: `Failed to process any valid rows. ${failedValidation} rows failed validation.\nPlease check the error details in the output.`,
      },
    },
  ];
}

// Generate warnings for missing columns (F&B and OtherRevenue)
const columnWarnings = [];
if (aggMissing.includes('fbRevenue')) {
  columnWarnings.push('WARNING: F&B Revenue column not detected. Using fallback column _35 or null values.');
}
if (aggMissing.includes('otherRevenue')) {
  columnWarnings.push('WARNING: Other/Extras Revenue column not detected. Using fallback column _38 or null values.');
}

// Push summary (ONLY requested observability fields)
allResults.push({
  json: {
    _summary: true,
    detected_format: detectedFormat,      // 'old' or 'new'
    hotel_name: hotelNameExtracted,
    header_rows_skipped: headerRowsSkipped,
    non_data_rows_skipped: nonDataRowsSkipped,
    missing_columns: aggMissing,          // after fallback
    missing_column_warnings: columnWarnings,
    used_fallback: usedFallbackAny,       // should be false for your sample now
    successfully_processed: successfullyProcessed,
    failed_validation: failedValidation,
    errors_count: failedValidation > 0 ? 1 : 0,
    column_detection_log: columnDetectionLog,  // For testing column detection
  },
});

// Push errors item if any
if (failedRows.length > 0) {
  allResults.push({
    json: {
      _errors: true,
      failed_rows: failedRows,
    },
  });
}

return allResults;

